<tool_call name="write_site">
<file path="src/components/Header.tsx">
import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`gc-header${scrolled ? ' gc-header--scrolled' : ''}`} role="banner">
      <div className="gc-header__inner">
        <a href="#" className="gc-header__logo" aria-label="Golden Crumb Bakery Home">
          Golden Crumb Bakery
        </a>

        <nav className="gc-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="gc-header__link">Home</a>
          <a href="#bakes" className="gc-header__link">Pastries & Breads</a>
          <a href="#footer" className="gc-header__link">Contact</a>
        </nav>

        <div className="gc-header__actions">
          <a href="mailto:orders@goldencrumb.com" className="gc-header__cta">
            Pre-Order Bakes
          </a>
          <button
            type="button"
            className="gc-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="gc-header__bar" />
            <span className="gc-header__bar" />
            <span className="gc-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="gc-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#bakes" onClick={() => setMenuOpen(false)}>Pastries & Breads</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

</file>
<file path="src/components/Header.css">
.gc-header {
  position: sticky;
  top: 0;
  z-index: 100;
  width: 100%;
  background: rgba(34, 25, 20, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.gc-header--scrolled {
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.4);
  border-bottom-color: #d97706;
}

.gc-header__inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 2rem;
  height: 74px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.gc-header__logo {
  font-family: 'Cinzel', sans-serif;
  font-size: 1.35rem;
  font-weight: 700;
  color: #fafafa;
  text-decoration: none;
  letter-spacing: -0.01em;
}

.gc-header__nav {
  display: flex;
  gap: 2rem;
  align-items: center;
}

.gc-header__link {
  color: #a1a1aa;
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 500;
  transition: color 0.2s ease;
}

.gc-header__link:hover {
  color: #d97706;
}

.gc-header__actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.gc-header__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.6rem 1.4rem;
  background: #d97706;
  color: #0c0d12;
  font-size: 0.88rem;
  font-weight: 700;
  text-decoration: none;
  border-radius: 6px;
  transition: all 0.2s ease;
}

.gc-header__cta:hover {
  background: #b45309;
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(217, 119, 6, 0.35);
}

.gc-header__toggle {
  display: none;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 6px;
  flex-direction: column;
  gap: 5px;
}

.gc-header__bar {
  display: block;
  width: 22px;
  height: 2px;
  background: #fafafa;
  border-radius: 2px;
}

.gc-header__mobile-menu {
  display: flex;
  flex-direction: column;
  padding: 1rem 2rem;
  background: #221914;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  gap: 0.75rem;
}

.gc-header__mobile-menu a {
  color: #fafafa;
  text-decoration: none;
  font-size: 1rem;
  padding: 0.5rem 0;
}

@media (max-width: 768px) {
  .gc-header__nav { display: none; }
  .gc-header__toggle { display: flex; }
}

@media (prefers-reduced-motion: reduce) {
  .gc-header,
  .gc-header__cta,
  .gc-header__link {
    transition: none !important;
    transform: none !important;
    animation: none !important;
  }
}

</file>
