<file path="src/components/PastriesBreads.tsx">
import React from 'react';
import './PastriesBreads.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Country Sourdough Boule",
    "tag": "$9.50",
    "desc": "36-hour cold ferment with stone-ground heritage whole wheat and caramelized blistered crust."
  },
  {
    "title": "Cardamom Almond Croissant",
    "tag": "$6.25",
    "desc": "Twice-baked laminated viennoiserie soaked in orange blossom syrup with toasted almond frangipane."
  },
  {
    "title": "Valrhona Chocolate Babka",
    "tag": "$14.00",
    "desc": "Brioche loaf braided with 70% dark chocolate fudge, Ceylon cinnamon, and crystal sugar syrup."
  },
  {
    "title": "Miso Hazelnut Kouign-Amann",
    "tag": "$5.75",
    "desc": "Breton butter pastry caramelized with salted white miso honey and roasted Piedmont hazelnuts."
  }
];

export function PastriesBreads() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.gc-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="gc-catalog" id="bakes" aria-labelledby="gc-catalog-title">
      <div className="gc-catalog__inner">
        <div className="gc-catalog__header">
          <p className="gc-catalog__eyebrow">Featured Highlights</p>
          <h2 id="gc-catalog-title" className="gc-catalog__title">
            Pastries & Breads
          </h2>
          <p className="gc-catalog__desc">
            Handcrafted sourdough loaves, French viennoiserie, and seasonal pastries baked fresh daily with stone-ground heritage flours.
          </p>
        </div>

        <div ref={gridRef} className="gc-catalog__grid">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="gc-card" style={{ transitionDelay: `${idx * 60}ms` }}>
              <div className="gc-card__top">
                <span className="gc-card__index">0{idx + 1}</span>
                <span className="gc-card__tag">{item.tag}</span>
              </div>
              <h3 className="gc-card__title">{item.title}</h3>
              <p className="gc-card__desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

