import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`wl-header${scrolled ? ' wl-header--scrolled' : ''}`} role="banner">
      <div className="wl-header__inner">
        <a href="#" className="wl-header__logo" aria-label="Wanderlust Expeditions Home">
          Wanderlust Expeditions
        </a>

        <nav className="wl-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="wl-header__link">Home</a>
          <a href="#expeditions" className="wl-header__link">Featured Journeys</a>
          <a href="#footer" className="wl-header__link">Contact</a>
        </nav>

        <div className="wl-header__actions">
          <a href="mailto:concierge@wanderlustexpeditions.com" className="wl-header__cta">
            Book Expedition
          </a>
          <button
            type="button"
            className="wl-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="wl-header__bar" />
            <span className="wl-header__bar" />
            <span className="wl-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="wl-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#expeditions" onClick={() => setMenuOpen(false)}>Featured Journeys</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

