import React from 'react';
import './FeaturedJourneys.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "Serengeti Migration & Crater",
    "tag": "10 Days",
    "desc": "Mobile luxury canvas tenting tracking seasonal wildebeest crossings with private Maasai guides."
  },
  {
    "step": "Phase 02",
    "title": "Patagonia Fjords & Glaciers",
    "tag": "12 Days",
    "desc": "Catamaran navigation through southern ice fields paired with Torres del Paine backcountry horse treks."
  },
  {
    "step": "Phase 03",
    "title": "Svalbard Polar Bear Quest",
    "tag": "8 Days",
    "desc": "Small expedition ice-class vessel cruising Spitsbergen pack ice under the midnight sun."
  },
  {
    "step": "Phase 04",
    "title": "Raja Ampat Coral Diving",
    "tag": "11 Days",
    "desc": "Traditional wooden phinisi yacht liveaboard exploring the biodiverse epicentre of the Coral Triangle."
  }
];

export function FeaturedJourneys() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.wl-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="wl-timeline" id="expeditions" aria-labelledby="wl-timeline-title">
      <div className="wl-timeline__inner">
        <div className="wl-timeline__header">
          <p className="wl-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="wl-timeline-title" className="wl-timeline__title">
            Featured Journeys
          </h2>
          <p className="wl-timeline__desc">
            Immersive small-group wildlife expeditions and luxury eco-lodges guided by expert field biologists across seven continents.
          </p>
        </div>

        <div ref={trackRef} className="wl-timeline__track">
          <div className="wl-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="wl-timeline__node">
              <div className="wl-timeline__marker" aria-hidden="true">
                <span className="wl-timeline__dot" />
              </div>
              <div className="wl-timeline__card">
                <div className="wl-timeline__card-top">
                  <span className="wl-timeline__step">{m.step}</span>
                  <span className="wl-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="wl-timeline__card-title">{m.title}</h3>
                <p className="wl-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

