import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`pc-header${scrolled ? ' pc-header--scrolled' : ''}`} role="banner">
      <div className="pc-header__inner">
        <a href="#" className="pc-header__logo" aria-label="Paws & Claws Animal Hospital Home">
          Paws & Claws Animal Hospital
        </a>

        <nav className="pc-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="pc-header__link">Home</a>
          <a href="#services" className="pc-header__link">Clinical Services</a>
          <a href="#footer" className="pc-header__link">Contact</a>
        </nav>

        <div className="pc-header__actions">
          <a href="mailto:care@pawsandclawsvet.com" className="pc-header__cta">
            Book Appointment
          </a>
          <button
            type="button"
            className="pc-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="pc-header__bar" />
            <span className="pc-header__bar" />
            <span className="pc-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="pc-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#services" onClick={() => setMenuOpen(false)}>Clinical Services</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

