import React from 'react';
import './ClinicalServices.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "24/7 Emergency & ICU Care",
    "tag": "Always Open",
    "desc": "Immediate critical care with oxygen therapy cages, blood transfusions, and continuous telemetry monitoring."
  },
  {
    "title": "Minimally Invasive Surgery",
    "tag": "Specialized",
    "desc": "Laparoscopic spays, soft tissue reconstructions, and orthopedic stifle stabilization with rapid recovery."
  },
  {
    "title": "Advanced Digital Radiology",
    "tag": "Diagnostics",
    "desc": "In-house 64-slice CT scans, high-resolution ultrasound, and certified board radiologist evaluations."
  },
  {
    "title": "Dental Prophylaxis & Surgery",
    "tag": "Preventative",
    "desc": "Full-mouth digital radiographs, ultrasonic scaling, and subgingival laser periodontal treatments."
  }
];

export function ClinicalServices() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.pc-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="pc-catalog" id="services" aria-labelledby="pc-catalog-title">
      <div className="pc-catalog__inner">
        <div className="pc-catalog__header">
          <p className="pc-catalog__eyebrow">Featured Highlights</p>
          <h2 id="pc-catalog-title" className="pc-catalog__title">
            Clinical Services
          </h2>
          <p className="pc-catalog__desc">
            Advanced veterinary surgical care, preventive medicine, and 24/7 emergency treatments for beloved companion animals.
          </p>
        </div>

        <div ref={gridRef} className="pc-catalog__grid">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="pc-card" style={{ transitionDelay: `${idx * 60}ms` }}>
              <div className="pc-card__top">
                <span className="pc-card__index">0{idx + 1}</span>
                <span className="pc-card__tag">{item.tag}</span>
              </div>
              <h3 className="pc-card__title">{item.title}</h3>
              <p className="pc-card__desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

