import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`fs-header${scrolled ? ' fs-header--scrolled' : ''}`} role="banner">
      <div className="fs-header__inner">
        <a href="#" className="fs-header__logo" aria-label="The Future Syntax Home">
          The Future Syntax
        </a>

        <nav className="fs-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="fs-header__link">Home</a>
          <a href="#episodes" className="fs-header__link">Latest Episodes</a>
          <a href="#footer" className="fs-header__link">Contact</a>
        </nav>

        <div className="fs-header__actions">
          <a href="mailto:producers@futuresyntaxpodcast.com" className="fs-header__cta">
            Listen on Spotify
          </a>
          <button
            type="button"
            className="fs-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="fs-header__bar" />
            <span className="fs-header__bar" />
            <span className="fs-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="fs-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#episodes" onClick={() => setMenuOpen(false)}>Latest Episodes</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

