}

@media (max-width: 900px) {
  .fs-hero__inner { grid-template-columns: 1fr; gap: 3rem; }
}

.fs-hero__left {
  animation: fsHeroLeftEnter 0.6s cubic-bezier(0.16, 1, 0.3, 1) 0ms both;
}

.fs-hero__right {
  animation: fsHeroRightEnter 0.6s cubic-bezier(0.16, 1, 0.3, 1) 160ms both;
}

@keyframes fsHeroLeftEnter {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fsHeroRightEnter {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .fs-hero__left,
  .fs-hero__right,
  .fs-hero__btn-primary,
  .fs-hero__btn-secondary {
    animation: none !important;
    transition: none !important;
    transform: none !important;
    opacity: 1 !important;
  }
}

