import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`th-header${scrolled ? ' th-header--scrolled' : ''}`} role="banner">
      <div className="th-header__inner">
        <a href="#" className="th-header__logo" aria-label="The Hive Collective Home">
          The Hive Collective
        </a>

        <nav className="th-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="th-header__link">Home</a>
          <a href="#memberships" className="th-header__link">Membership Tiers</a>
          <a href="#footer" className="th-header__link">Contact</a>
        </nav>

        <div className="th-header__actions">
          <a href="mailto:community@thehivecollective.co" className="th-header__cta">
            Book a Day Pass
          </a>
          <button
            type="button"
            className="th-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="th-header__bar" />
            <span className="th-header__bar" />
            <span className="th-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="th-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#memberships" onClick={() => setMenuOpen(false)}>Membership Tiers</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

