import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`hb-header${scrolled ? ' hb-header--scrolled' : ''}`} role="banner">
      <div className="hb-header__inner">
        <a href="#" className="hb-header__logo" aria-label="Hop & Barrel Brewing Co. Home">
          Hop & Barrel Brewing Co.
        </a>

        <nav className="hb-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="hb-header__link">Home</a>
          <a href="#taplist" className="hb-header__link">Current Taplist</a>
          <a href="#footer" className="hb-header__link">Contact</a>
        </nav>

        <div className="hb-header__actions">
          <a href="mailto:taproom@hopandbarrelbrewing.com" className="hb-header__cta">
            Explore Taplist
          </a>
          <button
            type="button"
            className="hb-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="hb-header__bar" />
            <span className="hb-header__bar" />
            <span className="hb-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="hb-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#taplist" onClick={() => setMenuOpen(false)}>Current Taplist</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

