import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ll-header${scrolled ? ' ll-header--scrolled' : ''}`} role="banner">
      <div className="ll-header__inner">
        <a href="#" className="ll-header__logo" aria-label="Lumina Living Studio Home">
          Lumina Living Studio
        </a>

        <nav className="ll-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ll-header__link">Home</a>
          <a href="#projects" className="ll-header__link">Signature Projects</a>
          <a href="#footer" className="ll-header__link">Contact</a>
        </nav>

        <div className="ll-header__actions">
          <a href="mailto:studio@luminaliving.design" className="ll-header__cta">
            View Portfolio
          </a>
          <button
            type="button"
            className="ll-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ll-header__bar" />
            <span className="ll-header__bar" />
            <span className="ll-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ll-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#projects" onClick={() => setMenuOpen(false)}>Signature Projects</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

