import React from 'react';
import './HeadliningStages.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "The Cyber Dome",
    "tag": "Stage 01",
    "desc": "360-degree spatial L-Acoustics array with real-time reactive AI visual projections and synthwave headliners."
  },
  {
    "step": "Phase 02",
    "title": "Subterranean Bass Hall",
    "tag": "Stage 02",
    "desc": "Industrial warehouse acoustics engineered for heavy analog sub-bass, experimental dubstep, and glitch art."
  },
  {
    "step": "Phase 03",
    "title": "Solstice Outdoor Arena",
    "tag": "Stage 03",
    "desc": "Open-air lakeside amphitheater for sunset melodic techno, live orchestral electronica, and drone shows."
  },
  {
    "step": "Phase 04",
    "title": "Ambient Chill Sanctuary",
    "tag": "Stage 04",
    "desc": "Binaural meditation dome with zero-gravity hammocks, herbal elixir bars, and modular synth live jams."
  }
];

export function HeadliningStages() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.ns-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="ns-timeline" id="stages" aria-labelledby="ns-timeline-title">
      <div className="ns-timeline__inner">
        <div className="ns-timeline__header">
          <p className="ns-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="ns-timeline-title" className="ns-timeline__title">
            Headlining Stages
          </h2>
          <p className="ns-timeline__desc">
            Three days of boundary-pushing electronic music, immersive spatial light installations, and world-class live producers.
          </p>
        </div>

        <div ref={trackRef} className="ns-timeline__track">
          <div className="ns-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="ns-timeline__node">
              <div className="ns-timeline__marker" aria-hidden="true">
                <span className="ns-timeline__dot" />
              </div>
              <div className="ns-timeline__card">
                <div className="ns-timeline__card-top">
                  <span className="ns-timeline__step">{m.step}</span>
                  <span className="ns-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="ns-timeline__card-title">{m.title}</h3>
                <p className="ns-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

