import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ev-header${scrolled ? ' ev-header--scrolled' : ''}`} role="banner">
      <div className="ev-header__inner">
        <a href="#" className="ev-header__logo" aria-label="Elena Voss Photography Home">
          Elena Voss Photography
        </a>

        <nav className="ev-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ev-header__link">Home</a>
          <a href="#portfolios" className="ev-header__link">Featured Portfolios</a>
          <a href="#footer" className="ev-header__link">Contact</a>
        </nav>

        <div className="ev-header__actions">
          <a href="mailto:studio@elenavossphoto.com" className="ev-header__cta">
            Book Editorial
          </a>
          <button
            type="button"
            className="ev-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ev-header__bar" />
            <span className="ev-header__bar" />
            <span className="ev-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ev-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#portfolios" onClick={() => setMenuOpen(false)}>Featured Portfolios</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

