import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sl-header${scrolled ? ' sl-header--scrolled' : ''}`} role="banner">
      <div className="sl-header__inner">
        <a href="#" className="sl-header__logo" aria-label="Serene Lotus Sanctuary Home">
          Serene Lotus Sanctuary
        </a>

        <nav className="sl-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sl-header__link">Home</a>
          <a href="#rituals" className="sl-header__link">Therapeutic Rituals</a>
          <a href="#footer" className="sl-header__link">Contact</a>
        </nav>

        <div className="sl-header__actions">
          <a href="mailto:sanctuary@serenelotusspa.com" className="sl-header__cta">
            Reserve Experience
          </a>
          <button
            type="button"
            className="sl-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sl-header__bar" />
            <span className="sl-header__bar" />
            <span className="sl-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sl-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#rituals" onClick={() => setMenuOpen(false)}>Therapeutic Rituals</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

