import React, { useState } from 'react';
import './TherapeuticRituals.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Hot Spring Hydrotherapy",
    "tag": "90 min",
    "desc": "Mineral-rich soaking pools with guided breathwork."
  },
  {
    "title": "Aromatherapy Herbal Massage",
    "tag": "60 min",
    "desc": "Wild mountain botanicals and heated river basalt stones."
  },
  {
    "title": "Bamboo Charcoal Sauna",
    "tag": "45 min",
    "desc": "Infrared detoxification and contrast ice bath plunge."
  },
  {
    "title": "Rejuvenating Pearl Facial",
    "tag": "75 min",
    "desc": "Organic marine collagen infusion and lymphatic sculpting."
  }
];

export function TherapeuticRituals() {
  const [activeTab, setActiveTab] = useState(0);

  return (
    <section className="sl-tabs" id="rituals" aria-labelledby="sl-tabs-title">
      <div className="sl-tabs__inner">
        <div className="sl-tabs__header">
          <p className="sl-tabs__eyebrow">Interactive Directory</p>
          <h2 id="sl-tabs-title" className="sl-tabs__title">
            Therapeutic Rituals
          </h2>
          <p className="sl-tabs__desc">
            Holistic geothermal soaking pools, botanical herbal aromatherapy, and traditional Japanese hot spring thermal therapies.
          </p>
        </div>

        <div className="sl-tabs__nav" role="tablist" aria-label="Therapeutic Rituals Tabs">
          {ITEMS.map((item, idx) => (
            <button
              key={item.title}
              type="button"
              role="tab"
              aria-selected={activeTab === idx}
              className={`sl-tabs__tab${activeTab === idx ? ' sl-tabs__tab--active' : ''}`}
              onClick={() => setActiveTab(idx)}
            >
              {item.title}
            </button>
          ))}
        </div>

        <div className="sl-tabs__showcase" role="tabpanel">
          <div className="sl-tabs__panel-top">
            <span className="sl-tabs__panel-tag">{ITEMS[activeTab]?.tag}</span>
            <span className="sl-tabs__panel-index">Tier 0{activeTab + 1}</span>
          </div>
          <h3 className="sl-tabs__panel-title">{ITEMS[activeTab]?.title}</h3>
          <p className="sl-tabs__panel-desc">{ITEMS[activeTab]?.desc}</p>
          <div className="sl-tabs__panel-footer">
            <a href="mailto:sanctuary@serenelotusspa.com" className="sl-tabs__btn">
              Inquire About {ITEMS[activeTab]?.title}
            </a>
          </div>
        </div>

        <div className="sl-tabs__grid">
          {ITEMS.map((item, idx) => (
            <div
              key={item.title}
              className={`sl-tabs__card${activeTab === idx ? ' sl-tabs__card--active' : ''}`}
              onClick={() => setActiveTab(idx)}
            >
              <div className="sl-tabs__card-top">
                <span className="sl-tabs__card-num">0{idx + 1}</span>
                <span className="sl-tabs__card-tag">{item.tag}</span>
              </div>
              <h4 className="sl-tabs__card-title">{item.title}</h4>
              <p className="sl-tabs__card-desc">{item.desc}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

