import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`he-header${scrolled ? ' he-header--scrolled' : ''}`} role="banner">
      <div className="he-header__inner">
        <a href="#" className="he-header__logo" aria-label="Helios Clean Energy Home">
          Helios Clean Energy
        </a>

        <nav className="he-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="he-header__link">Home</a>
          <a href="#solutions" className="he-header__link">Solar Solutions</a>
          <a href="#footer" className="he-header__link">Contact</a>
        </nav>

        <div className="he-header__actions">
          <a href="mailto:solutions@helioscleanenergy.com" className="he-header__cta">
            Get Solar Quote
          </a>
          <button
            type="button"
            className="he-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="he-header__bar" />
            <span className="he-header__bar" />
            <span className="he-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="he-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#solutions" onClick={() => setMenuOpen(false)}>Solar Solutions</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

