import React from 'react';
import './SolarSolutions.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "High-Efficiency Monocrystalline Panels",
    "tag": "25yr Warranty",
    "desc": "Sleek all-black panels boasting 22.8% energy conversion."
  },
  {
    "step": "Phase 02",
    "title": "Smart Lithium Home Battery",
    "tag": "13.5 kWh",
    "desc": "Instant backup power during grid blackouts with app controls."
  },
  {
    "step": "Phase 03",
    "title": "EV Supercharger Integration",
    "tag": "Level 2 Fast",
    "desc": "Direct clean solar charging for electric vehicles."
  },
  {
    "step": "Phase 04",
    "title": "Commercial Micro-Grid Systems",
    "tag": "Custom",
    "desc": "Zero-downtime decentralized solar for industrial warehouses."
  }
];

export function SolarSolutions() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.he-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="he-timeline" id="solutions" aria-labelledby="he-timeline-title">
      <div className="he-timeline__inner">
        <div className="he-timeline__header">
          <p className="he-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="he-timeline-title" className="he-timeline__title">
            Solar Solutions
          </h2>
          <p className="he-timeline__desc">
            Tier-1 monocrystalline rooftop solar installations, residential battery storage, and smart micro-grid energy management.
          </p>
        </div>

        <div ref={trackRef} className="he-timeline__track">
          <div className="he-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="he-timeline__node">
              <div className="he-timeline__marker" aria-hidden="true">
                <span className="he-timeline__dot" />
              </div>
              <div className="he-timeline__card">
                <div className="he-timeline__card-top">
                  <span className="he-timeline__step">{m.step}</span>
                  <span className="he-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="he-timeline__card-title">{m.title}</h3>
                <p className="he-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

