import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`az-header${scrolled ? ' az-header--scrolled' : ''}`} role="banner">
      <div className="az-header__inner">
        <a href="#" className="az-header__logo" aria-label="Aegis Zero-Trust Security Home">
          Aegis Zero-Trust Security
        </a>

        <nav className="az-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="az-header__link">Home</a>
          <a href="#platform" className="az-header__link">Security Architecture</a>
          <a href="#footer" className="az-header__link">Contact</a>
        </nav>

        <div className="az-header__actions">
          <a href="mailto:soc@aegiszerotrust.com" className="az-header__cta">
            Deploy Platform
          </a>
          <button
            type="button"
            className="az-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="az-header__bar" />
            <span className="az-header__bar" />
            <span className="az-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="az-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#platform" onClick={() => setMenuOpen(false)}>Security Architecture</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

