import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`is-header${scrolled ? ' is-header--scrolled' : ''}`} role="banner">
      <div className="is-header__inner">
        <a href="#" className="is-header__logo" aria-label="Iron & Shears Parlour Home">
          Iron & Shears Parlour
        </a>

        <nav className="is-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="is-header__link">Home</a>
          <a href="#services" className="is-header__link">Grooming Menu</a>
          <a href="#footer" className="is-header__link">Contact</a>
        </nav>

        <div className="is-header__actions">
          <a href="mailto:chair@ironshearsparlour.com" className="is-header__cta">
            Book Appointment
          </a>
          <button
            type="button"
            className="is-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="is-header__bar" />
            <span className="is-header__bar" />
            <span className="is-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="is-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#services" onClick={() => setMenuOpen(false)}>Grooming Menu</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

