import React from 'react';
import './GroomingMenu.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Signature Scissor Cut & Style",
    "tag": "$45",
    "desc": "Precision haircut with hot towel neck shave and tonic massage."
  },
  {
    "title": "Traditional Straight-Razor Shave",
    "tag": "$40",
    "desc": "Pre-shave essential oils, warm lather, and cold stone finish."
  },
  {
    "title": "Beard Sculpting & Conditioning",
    "tag": "$30",
    "desc": "Crisp line definition, shears tapering, and beard butter treatment."
  },
  {
    "title": "The Executive Combo Experience",
    "tag": "$70",
    "desc": "Full haircut, complete hot-lather shave, and facial scrub."
  }
];

export function GroomingMenu() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.is-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="is-catalog" id="services" aria-labelledby="is-catalog-title">
      <div className="is-catalog__inner">
        <div className="is-catalog__header">
          <p className="is-catalog__eyebrow">Featured Highlights</p>
          <h2 id="is-catalog-title" className="is-catalog__title">
            Grooming Menu
          </h2>
          <p className="is-catalog__desc">
            Master straight-razor hot lather shaves, precision scissor cuts, and luxury beard conditioning in a classic heritage parlour.
          </p>
        </div>

        <div ref={gridRef} className="is-catalog__grid">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="is-card" style={{ transitionDelay: `${idx * 60}ms` }}>
              <div className="is-card__top">
                <span className="is-card__index">0{idx + 1}</span>
                <span className="is-card__tag">{item.tag}</span>
              </div>
              <h3 className="is-card__title">{item.title}</h3>
              <p className="is-card__desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

