import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sr-header${scrolled ? ' sr-header--scrolled' : ''}`} role="banner">
      <div className="sr-header__inner">
        <a href="#" className="sr-header__logo" aria-label="Savory Roots Catering Home">
          Savory Roots Catering
        </a>

        <nav className="sr-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sr-header__link">Home</a>
          <a href="#menus" className="sr-header__link">Seasonal Menus</a>
          <a href="#footer" className="sr-header__link">Contact</a>
        </nav>

        <div className="sr-header__actions">
          <a href="mailto:events@savoryrootscatering.com" className="sr-header__cta">
            Request Tasting
          </a>
          <button
            type="button"
            className="sr-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sr-header__bar" />
            <span className="sr-header__bar" />
            <span className="sr-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sr-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#menus" onClick={() => setMenuOpen(false)}>Seasonal Menus</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

