import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ba-header${scrolled ? ' ba-header--scrolled' : ''}`} role="banner">
      <div className="ba-header__inner">
        <a href="#" className="ba-header__logo" aria-label="Botanica Floral Atelier Home">
          Botanica Floral Atelier
        </a>

        <nav className="ba-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ba-header__link">Home</a>
          <a href="#arrangements" className="ba-header__link">Signature Arrangements</a>
          <a href="#footer" className="ba-header__link">Contact</a>
        </nav>

        <div className="ba-header__actions">
          <a href="mailto:blooms@botanicaatelier.com" className="ba-header__cta">
            Order Floral Design
          </a>
          <button
            type="button"
            className="ba-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ba-header__bar" />
            <span className="ba-header__bar" />
            <span className="ba-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ba-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#arrangements" onClick={() => setMenuOpen(false)}>Signature Arrangements</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

