import React from 'react';
import './SignatureArrangements.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "The Ikebana Minimalist",
    "tag": "$120",
    "desc": "Architectural branches, single heirloom peonies, and raku ceramic vase."
  },
  {
    "title": "Meadow Wildflower Centerpiece",
    "tag": "$180",
    "desc": "Lush garden roses, chamomile, Queen Anne's lace, and eucalyptus."
  },
  {
    "title": "Monochrome Dahlia Cascade",
    "tag": "$210",
    "desc": "Deep burgundy dinnerplate dahlias with cascading amaranthus."
  },
  {
    "title": "Bespoke Wedding Arch Installation",
    "tag": "Custom",
    "desc": "Floor-to-ceiling dried florals, pampas grass, and live orchids."
  }
];

export function SignatureArrangements() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.ba-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="ba-catalog" id="arrangements" aria-labelledby="ba-catalog-title">
      <div className="ba-catalog__inner">
        <div className="ba-catalog__header">
          <p className="ba-catalog__eyebrow">Featured Highlights</p>
          <h2 id="ba-catalog-title" className="ba-catalog__title">
            Signature Arrangements
          </h2>
          <p className="ba-catalog__desc">
            Architectural botanical arrangements, sculptural Ikebana installations, and bespoke event florals sourced from local growers.
          </p>
        </div>

        <div ref={gridRef} className="ba-catalog__grid">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="ba-card" style={{ transitionDelay: `${idx * 60}ms` }}>
              <div className="ba-card__top">
                <span className="ba-card__index">0{idx + 1}</span>
                <span className="ba-card__tag">{item.tag}</span>
              </div>
              <h3 className="ba-card__title">{item.title}</h3>
              <p className="ba-card__desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

