import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sc-header${scrolled ? ' sc-header--scrolled' : ''}`} role="banner">
      <div className="sc-header__inner">
        <a href="#" className="sc-header__logo" aria-label="SparkClean Facilities Home">
          SparkClean Facilities
        </a>

        <nav className="sc-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sc-header__link">Home</a>
          <a href="#services" className="sc-header__link">Commercial Solutions</a>
          <a href="#footer" className="sc-header__link">Contact</a>
        </nav>

        <div className="sc-header__actions">
          <a href="mailto:dispatch@sparkcleanfacilities.com" className="sc-header__cta">
            Get Facility Quote
          </a>
          <button
            type="button"
            className="sc-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sc-header__bar" />
            <span className="sc-header__bar" />
            <span className="sc-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sc-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#services" onClick={() => setMenuOpen(false)}>Commercial Solutions</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

