import React from 'react';
import './CommercialSolutions.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "Nightly Green Janitorial",
    "tag": "Daily Service",
    "desc": "Non-toxic HEPA vacuuming, surface sanitation, and waste sorting."
  },
  {
    "step": "Phase 02",
    "title": "Commercial Carpet Deep Extraction",
    "tag": "Periodic",
    "desc": "Hot-water extraction neutralizing stains and deep allergens."
  },
  {
    "step": "Phase 03",
    "title": "High-Rise Exterior Window Washing",
    "tag": "Specialized",
    "desc": "OSHA-compliant rope-access glass cleaning for glass facades."
  },
  {
    "step": "Phase 04",
    "title": "Post-Construction Terminal Clean",
    "tag": "Turnkey",
    "desc": "Complete dust abatement and scrubbing ready for tenant handover."
  }
];

export function CommercialSolutions() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.sc-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="sc-timeline" id="services" aria-labelledby="sc-timeline-title">
      <div className="sc-timeline__inner">
        <div className="sc-timeline__header">
          <p className="sc-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="sc-timeline-title" className="sc-timeline__title">
            Commercial Solutions
          </h2>
          <p className="sc-timeline__desc">
            Eco-certified commercial office sanitation, HEPA air purification, and rope-access exterior architectural window washing.
          </p>
        </div>

        <div ref={trackRef} className="sc-timeline__track">
          <div className="sc-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="sc-timeline__node">
              <div className="sc-timeline__marker" aria-hidden="true">
                <span className="sc-timeline__dot" />
              </div>
              <div className="sc-timeline__card">
                <div className="sc-timeline__card-top">
                  <span className="sc-timeline__step">{m.step}</span>
                  <span className="sc-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="sc-timeline__card-title">{m.title}</h3>
                <p className="sc-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

