import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`vg-header${scrolled ? ' vg-header--scrolled' : ''}`} role="banner">
      <div className="vg-header__inner">
        <a href="#" className="vg-header__logo" aria-label="Vanguard Global Freight Home">
          Vanguard Global Freight
        </a>

        <nav className="vg-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="vg-header__link">Home</a>
          <a href="#network" className="vg-header__link">Logistics Networks</a>
          <a href="#footer" className="vg-header__link">Contact</a>
        </nav>

        <div className="vg-header__actions">
          <a href="mailto:customs@vanguardfreight.com" className="vg-header__cta">
            Track Shipment
          </a>
          <button
            type="button"
            className="vg-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="vg-header__bar" />
            <span className="vg-header__bar" />
            <span className="vg-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="vg-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#network" onClick={() => setMenuOpen(false)}>Logistics Networks</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

