import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ac-header${scrolled ? ' ac-header--scrolled' : ''}`} role="banner">
      <div className="ac-header__inner">
        <a href="#" className="ac-header__logo" aria-label="Azure Cove Beach Resort Home">
          Azure Cove Beach Resort
        </a>

        <nav className="ac-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ac-header__link">Home</a>
          <a href="#suites" className="ac-header__link">Private Villas</a>
          <a href="#footer" className="ac-header__link">Contact</a>
        </nav>

        <div className="ac-header__actions">
          <a href="mailto:concierge@azurecoveresort.com" className="ac-header__cta">
            Reserve Suite
          </a>
          <button
            type="button"
            className="ac-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ac-header__bar" />
            <span className="ac-header__bar" />
            <span className="ac-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ac-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#suites" onClick={() => setMenuOpen(false)}>Private Villas</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

