import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`mp-header${scrolled ? ' mp-header--scrolled' : ''}`} role="banner">
      <div className="mp-header__inner">
        <a href="#" className="mp-header__logo" aria-label="Mindful Pathways Therapy Home">
          Mindful Pathways Therapy
        </a>

        <nav className="mp-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="mp-header__link">Home</a>
          <a href="#specialties" className="mp-header__link">Clinical Specialties</a>
          <a href="#footer" className="mp-header__link">Contact</a>
        </nav>

        <div className="mp-header__actions">
          <a href="mailto:intake@mindfulpathwaystherapy.com" className="mp-header__cta">
            Book Initial Intake
          </a>
          <button
            type="button"
            className="mp-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="mp-header__bar" />
            <span className="mp-header__bar" />
            <span className="mp-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="mp-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#specialties" onClick={() => setMenuOpen(false)}>Clinical Specialties</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

