import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`tf-header${scrolled ? ' tf-header--scrolled' : ''}`} role="banner">
      <div className="tf-header__inner">
        <a href="#" className="tf-header__logo" aria-label="TalentForge Search Partners Home">
          TalentForge Search Partners
        </a>

        <nav className="tf-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="tf-header__link">Home</a>
          <a href="#practices" className="tf-header__link">Search Practices</a>
          <a href="#footer" className="tf-header__link">Contact</a>
        </nav>

        <div className="tf-header__actions">
          <a href="mailto:partners@talentforgesearch.com" className="tf-header__cta">
            Hire Top Talent
          </a>
          <button
            type="button"
            className="tf-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="tf-header__bar" />
            <span className="tf-header__bar" />
            <span className="tf-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="tf-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#practices" onClick={() => setMenuOpen(false)}>Search Practices</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

