import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`pp-header${scrolled ? ' pp-header--scrolled' : ''}`} role="banner">
      <div className="pp-header__inner">
        <a href="#" className="pp-header__logo" aria-label="Press & Paper Studio Home">
          Press & Paper Studio
        </a>

        <nav className="pp-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="pp-header__link">Home</a>
          <a href="#techniques" className="pp-header__link">Print Techniques</a>
          <a href="#footer" className="pp-header__link">Contact</a>
        </nav>

        <div className="pp-header__actions">
          <a href="mailto:orders@pressandpaperstudio.com" className="pp-header__cta">
            Order Sample Pack
          </a>
          <button
            type="button"
            className="pp-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="pp-header__bar" />
            <span className="pp-header__bar" />
            <span className="pp-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="pp-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#techniques" onClick={() => setMenuOpen(false)}>Print Techniques</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

