import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`vp-header${scrolled ? ' vp-header--scrolled' : ''}`} role="banner">
      <div className="vp-header__inner">
        <a href="#" className="vp-header__logo" aria-label="Valle di Pietra Estate Home">
          Valle di Pietra Estate
        </a>

        <nav className="vp-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="vp-header__link">Home</a>
          <a href="#vintages" className="vp-header__link">Current Vintages</a>
          <a href="#footer" className="vp-header__link">Contact</a>
        </nav>

        <div className="vp-header__actions">
          <a href="mailto:tasting@valledipietraestate.com" className="vp-header__cta">
            Shop Allocations
          </a>
          <button
            type="button"
            className="vp-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="vp-header__bar" />
            <span className="vp-header__bar" />
            <span className="vp-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="vp-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#vintages" onClick={() => setMenuOpen(false)}>Current Vintages</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

