import React from 'react';
import './CurrentVintages.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "2021 Reserve Cabernet Sauvignon",
    "tag": "96 Points",
    "desc": "French oak aged 22 months. Notes of cassis, graphite, and violet."
  },
  {
    "step": "Phase 02",
    "title": "2023 Estate Old-Vine Chardonnay",
    "tag": "94 Points",
    "desc": "Native yeast fermentation with crisp brioche and green apple minerality."
  },
  {
    "step": "Phase 03",
    "title": "2022 Hillside Syrah",
    "tag": "95 Points",
    "desc": "Whole-cluster pressed with black peppercorn, blackberry, and smoked meat."
  },
  {
    "step": "Phase 04",
    "title": "Late Harvest Botrytis Semillon",
    "tag": "Dessert",
    "desc": "Golden nectar featuring candied apricot, wild honeycomb, and bright acidity."
  }
];

export function CurrentVintages() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.vp-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="vp-timeline" id="vintages" aria-labelledby="vp-timeline-title">
      <div className="vp-timeline__inner">
        <div className="vp-timeline__header">
          <p className="vp-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="vp-timeline-title" className="vp-timeline__title">
            Current Vintages
          </h2>
          <p className="vp-timeline__desc">
            Estate-grown biodynamic hillside vintages fermented with native yeasts and aged in French oak barrels.
          </p>
        </div>

        <div ref={trackRef} className="vp-timeline__track">
          <div className="vp-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="vp-timeline__node">
              <div className="vp-timeline__marker" aria-hidden="true">
                <span className="vp-timeline__dot" />
              </div>
              <div className="vp-timeline__card">
                <div className="vp-timeline__card-top">
                  <span className="vp-timeline__step">{m.step}</span>
                  <span className="vp-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="vp-timeline__card-title">{m.title}</h3>
                <p className="vp-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

