import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ss-header${scrolled ? ' ss-header--scrolled' : ''}`} role="banner">
      <div className="ss-header__inner">
        <a href="#" className="ss-header__logo" aria-label="Summit Shield Roofing Home">
          Summit Shield Roofing
        </a>

        <nav className="ss-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ss-header__link">Home</a>
          <a href="#services" className="ss-header__link">Roofing Services</a>
          <a href="#footer" className="ss-header__link">Contact</a>
        </nav>

        <div className="ss-header__actions">
          <a href="mailto:service@summitshieldroofing.com" className="ss-header__cta">
            Get Free Roof Drone Scan
          </a>
          <button
            type="button"
            className="ss-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ss-header__bar" />
            <span className="ss-header__bar" />
            <span className="ss-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ss-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#services" onClick={() => setMenuOpen(false)}>Roofing Services</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

