import React from 'react';
import './RoofingServices.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Standing Seam Architectural Metal",
    "tag": "50yr Life",
    "desc": "Zero-exposed fastener metal panels resistant to 140mph winds."
  },
  {
    "title": "Impact-Resistant Class 4 Shingles",
    "tag": "Storm Proof",
    "desc": "Hail-rated asphalt shingles qualifying for major insurance discounts."
  },
  {
    "title": "Commercial TPO Flat Roof Systems",
    "tag": "Commercial",
    "desc": "Heat-welded waterproof membranes for energy-efficient flat roofs."
  },
  {
    "title": "Emergency Tarping & Drone Inspection",
    "tag": "24/7 Response",
    "desc": "High-res thermal drone scans detecting subsurface water intrusion."
  }
];

export function RoofingServices() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.ss-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="ss-catalog" id="services" aria-labelledby="ss-catalog-title">
      <div className="ss-catalog__inner">
        <div className="ss-catalog__header">
          <p className="ss-catalog__eyebrow">Featured Highlights</p>
          <h2 id="ss-catalog-title" className="ss-catalog__title">
            Roofing Services
          </h2>
          <p className="ss-catalog__desc">
            Standing-seam architectural metal roofs, impact-resistant shingles, and commercial flat roof thermoplastic membranes.
          </p>
        </div>

        <div ref={gridRef} className="ss-catalog__grid">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="ss-card" style={{ transitionDelay: `${idx * 60}ms` }}>
              <div className="ss-card__top">
                <span className="ss-card__index">0{idx + 1}</span>
                <span className="ss-card__tag">{item.tag}</span>
              </div>
              <h3 className="ss-card__title">{item.title}</h3>
              <p className="ss-card__desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

