import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`pd-header${scrolled ? ' pd-header--scrolled' : ''}`} role="banner">
      <div className="pd-header__inner">
        <a href="#" className="pd-header__logo" aria-label="Pearl Aesthetic Dentistry Home">
          Pearl Aesthetic Dentistry
        </a>

        <nav className="pd-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="pd-header__link">Home</a>
          <a href="#treatments" className="pd-header__link">Smile Treatments</a>
          <a href="#footer" className="pd-header__link">Contact</a>
        </nav>

        <div className="pd-header__actions">
          <a href="mailto:appointments@pearldentalspa.com" className="pd-header__cta">
            Book Smile Consult
          </a>
          <button
            type="button"
            className="pd-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="pd-header__bar" />
            <span className="pd-header__bar" />
            <span className="pd-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="pd-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#treatments" onClick={() => setMenuOpen(false)}>Smile Treatments</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

