import React, { useState } from 'react';
import './SmileTreatments.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Handcrafted Porcelain Veneers",
    "tag": "Cosmetic",
    "desc": "Ultra-thin custom porcelain shells correcting shape and spacing."
  },
  {
    "title": "Invisalign Clear Aligners",
    "tag": "Orthodontics",
    "desc": "Discreet orthodontic tooth straightening monitored via 3D scanning."
  },
  {
    "title": "Laser Teeth Brightening",
    "tag": "Whitening",
    "desc": "Safe in-office laser activation brightening smiles up to 8 shades in 60m."
  },
  {
    "title": "Guided Ceramic Dental Implants",
    "tag": "Restorative",
    "desc": "Biocompatible zirconia implants permanently replacing missing teeth."
  }
];

export function SmileTreatments() {
  const [activeTab, setActiveTab] = useState(0);

  return (
    <section className="pd-tabs" id="treatments" aria-labelledby="pd-tabs-title">
      <div className="pd-tabs__inner">
        <div className="pd-tabs__header">
          <p className="pd-tabs__eyebrow">Interactive Directory</p>
          <h2 id="pd-tabs-title" className="pd-tabs__title">
            Smile Treatments
          </h2>
          <p className="pd-tabs__desc">
            Minimally invasive porcelain veneers, discreet clear aligner orthodontics, and restorative ceramic implantology.
          </p>
        </div>

        <div className="pd-tabs__nav" role="tablist" aria-label="Smile Treatments Tabs">
          {ITEMS.map((item, idx) => (
            <button
              key={item.title}
              type="button"
              role="tab"
              aria-selected={activeTab === idx}
              className={`pd-tabs__tab${activeTab === idx ? ' pd-tabs__tab--active' : ''}`}
              onClick={() => setActiveTab(idx)}
            >
              {item.title}
            </button>
          ))}
        </div>

        <div className="pd-tabs__showcase" role="tabpanel">
          <div className="pd-tabs__panel-top">
            <span className="pd-tabs__panel-tag">{ITEMS[activeTab]?.tag}</span>
            <span className="pd-tabs__panel-index">Tier 0{activeTab + 1}</span>
          </div>
          <h3 className="pd-tabs__panel-title">{ITEMS[activeTab]?.title}</h3>
          <p className="pd-tabs__panel-desc">{ITEMS[activeTab]?.desc}</p>
          <div className="pd-tabs__panel-footer">
            <a href="mailto:appointments@pearldentalspa.com" className="pd-tabs__btn">
              Inquire About {ITEMS[activeTab]?.title}
            </a>
          </div>
        </div>

        <div className="pd-tabs__grid">
          {ITEMS.map((item, idx) => (
            <div
              key={item.title}
              className={`pd-tabs__card${activeTab === idx ? ' pd-tabs__card--active' : ''}`}
              onClick={() => setActiveTab(idx)}
            >
              <div className="pd-tabs__card-top">
                <span className="pd-tabs__card-num">0{idx + 1}</span>
                <span className="pd-tabs__card-tag">{item.tag}</span>
              </div>
              <h4 className="pd-tabs__card-title">{item.title}</h4>
              <p className="pd-tabs__card-desc">{item.desc}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

