import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`fp-header${scrolled ? ' fp-header--scrolled' : ''}`} role="banner">
      <div className="fp-header__inner">
        <a href="#" className="fp-header__logo" aria-label="FlowPro Master Plumbers Home">
          FlowPro Master Plumbers
        </a>

        <nav className="fp-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="fp-header__link">Home</a>
          <a href="#services" className="fp-header__link">Plumbing Services</a>
          <a href="#footer" className="fp-header__link">Contact</a>
        </nav>

        <div className="fp-header__actions">
          <a href="mailto:dispatch@flowproplumbers.com" className="fp-header__cta">
            Call Emergency Dispatch
          </a>
          <button
            type="button"
            className="fp-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="fp-header__bar" />
            <span className="fp-header__bar" />
            <span className="fp-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="fp-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#services" onClick={() => setMenuOpen(false)}>Plumbing Services</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

