import React from 'react';
import './AcademyPrograms.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "Adult Brazilian Jiu-Jitsu (Gi)",
    "tag": "All Levels",
    "desc": "Fundamental positional control, escapes, guard passing, and submissions."
  },
  {
    "step": "Phase 02",
    "title": "No-Gi Submission Grappling",
    "tag": "Advanced",
    "desc": "Wrestling takedowns, leg locks, and rapid transitional pressure."
  },
  {
    "step": "Phase 03",
    "title": "Authentic Muay Thai Striking",
    "tag": "Cardio & Technique",
    "desc": "Dutch kickboxing combinations, heavy bag circuits, and clinch sparring."
  },
  {
    "step": "Phase 04",
    "title": "Youth Champions Martial Arts",
    "tag": "Ages 5\u201314",
    "desc": "Bully prevention, discipline, self-defense, and balance fundamentals."
  }
];

export function AcademyPrograms() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.ro-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="ro-timeline" id="programs" aria-labelledby="ro-timeline-title">
      <div className="ro-timeline__inner">
        <div className="ro-timeline__header">
          <p className="ro-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="ro-timeline-title" className="ro-timeline__title">
            Academy Programs
          </h2>
          <p className="ro-timeline__desc">
            Authentic Brazilian Jiu-Jitsu, submission grappling, and Dutch-style Muay Thai striking taught by world-class champions.
          </p>
        </div>

        <div ref={trackRef} className="ro-timeline__track">
          <div className="ro-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="ro-timeline__node">
              <div className="ro-timeline__marker" aria-hidden="true">
                <span className="ro-timeline__dot" />
              </div>
              <div className="ro-timeline__card">
                <div className="ro-timeline__card-top">
                  <span className="ro-timeline__step">{m.step}</span>
                  <span className="ro-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="ro-timeline__card-title">{m.title}</h3>
                <p className="ro-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

