import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`iw-header${scrolled ? ' iw-header--scrolled' : ''}`} role="banner">
      <div className="iw-header__inner">
        <a href="#" className="iw-header__logo" aria-label="The Inkwell Rare Books Home">
          The Inkwell Rare Books
        </a>

        <nav className="iw-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="iw-header__link">Home</a>
          <a href="#volumes" className="iw-header__link">Rare Volumes</a>
          <a href="#footer" className="iw-header__link">Contact</a>
        </nav>

        <div className="iw-header__actions">
          <a href="mailto:curator@theinkwellshelf.com" className="iw-header__cta">
            Browse Catalog
          </a>
          <button
            type="button"
            className="iw-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="iw-header__bar" />
            <span className="iw-header__bar" />
            <span className="iw-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="iw-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#volumes" onClick={() => setMenuOpen(false)}>Rare Volumes</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

