import React from 'react';
import './LandscapeDisciplines.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Architectural Paver Patios & Firepits",
    "tag": "Hardscapes",
    "desc": "Permeable bluestone paving with integrated natural gas fire features."
  },
  {
    "title": "Native Xeriscape Plantings",
    "tag": "Water-Wise",
    "desc": "Drought-tolerant ornamental grasses, lavender, and drip irrigation."
  },
  {
    "title": "Custom Outdoor Kitchens & Pergolas",
    "tag": "Outdoor Living",
    "desc": "Built-in stainless grills, pizza ovens, and cedar timber shade structures."
  },
  {
    "title": "Low-Voltage LED Landscape Lighting",
    "tag": "Illumination",
    "desc": "Subtle warm-wash illumination highlighting specimen trees and pathways."
  }
];

export function LandscapeDisciplines() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.tv-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="tv-catalog" id="disciplines" aria-labelledby="tv-catalog-title">
      <div className="tv-catalog__inner">
        <div className="tv-catalog__header">
          <p className="tv-catalog__eyebrow">Featured Highlights</p>
          <h2 id="tv-catalog-title" className="tv-catalog__title">
            Landscape Disciplines
          </h2>
          <p className="tv-catalog__desc">
            Drought-tolerant native plant architecture, bluestone paver patios, and integrated outdoor living environments.
          </p>
        </div>

        <div ref={gridRef} className="tv-catalog__grid">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="tv-card" style={{ transitionDelay: `${idx * 60}ms` }}>
              <div className="tv-card__top">
                <span className="tv-card__index">0{idx + 1}</span>
                <span className="tv-card__tag">{item.tag}</span>
              </div>
              <h3 className="tv-card__title">{item.title}</h3>
              <p className="tv-card__desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

