import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ap-header${scrolled ? ' ap-header--scrolled' : ''}`} role="banner">
      <div className="ap-header__inner">
        <a href="#" className="ap-header__logo" aria-label="Apex Ceramic Studio Home">
          Apex Ceramic Studio
        </a>

        <nav className="ap-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ap-header__link">Home</a>
          <a href="#packages" className="ap-header__link">Protection Packages</a>
          <a href="#footer" className="ap-header__link">Contact</a>
        </nav>

        <div className="ap-header__actions">
          <a href="mailto:booking@apexceramicstudio.com" className="ap-header__cta">
            Reserve Detail Slot
          </a>
          <button
            type="button"
            className="ap-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ap-header__bar" />
            <span className="ap-header__bar" />
            <span className="ap-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ap-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#packages" onClick={() => setMenuOpen(false)}>Protection Packages</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

