  },
  {
    "title": "Commercial Cargo in Transit",
    "tag": "Ocean & Air",
    "desc": "All-risk cargo protection covering warehouse-to-warehouse international freight."
  },
  {
    "title": "Marina & Shipyard Operator Liability",
    "tag": "Commercial",
    "desc": "Pollution indemnity, ship repairer legal liability, and storm surge damage."
  },
  {
    "title": "Crew Healthcare & P&I Coverage",
    "tag": "Protection & Indemnity",
    "desc": "Medical evacuation and maritime employer liability for international crews."
  }
];

export function CoveragePolicies() {
  return (
    <section className="sh-bento" id="policies" aria-labelledby="sh-bento-title">
      <div className="sh-bento__inner">
        <div className="sh-bento__header">
          <p className="sh-bento__eyebrow">Modular Architecture</p>
          <h2 id="sh-bento-title" className="sh-bento__title">
