          </h2>
          <p className="sh-bento__desc">
            Comprehensive commercial marine hull insurance, worldwide superyacht coverage, and international cargo transit protection.
          </p>
        </div>

        <div className="sh-bento__grid">
          {ITEMS.length > 0 && (
            <article className="sh-bento__card sh-bento__card--featured">
              <div className="sh-bento__card-top">
                <span className="sh-bento__badge">FLAGSHIP SYSTEM</span>
                <span className="sh-bento__tag">{ITEMS[0].tag}</span>
              </div>
              <h3 className="sh-bento__card-title">{ITEMS[0].title}</h3>
              <p className="sh-bento__card-desc">{ITEMS[0].desc}</p>
              <div className="sh-bento__card-footer">
                <span className="sh-bento__status-dot" aria-hidden="true" />
                <span className="sh-bento__status-text">Production Verified</span>
              </div>
            </article>
          )}

          {ITEMS.length > 1 && (
            <article className="sh-bento__card sh-bento__card--tall">
              <div className="sh-bento__card-top">
                <span className="sh-bento__index">02</span>
                <span className="sh-bento__tag">{ITEMS[1].tag}</span>
              </div>
              <h3 className="sh-bento__card-title">{ITEMS[1].title}</h3>
              <p className="sh-bento__card-desc">{ITEMS[1].desc}</p>
              <div className="sh-bento__meter">
                <div className="sh-bento__meter-bar">
                  <div className="sh-bento__meter-fill" style={{ width: '92%' }} />
                </div>
                <span className="sh-bento__meter-label">92% Operational Efficiency</span>
              </div>
            </article>
          )}

          {ITEMS.slice(2).map((item, idx) => (
            <article key={item.title} className="sh-bento__card sh-bento__card--compact">
              <div className="sh-bento__card-top">
                <span className="sh-bento__index">0{idx + 3}</span>
                <span className="sh-bento__tag">{item.tag}</span>
              </div>
              <h3 className="sh-bento__card-title">{item.title}</h3>
              <p className="sh-bento__card-desc">{item.desc}</p>
            </article>
          ))}
