import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ek-header${scrolled ? ' ek-header--scrolled' : ''}`} role="banner">
      <div className="ek-header__inner">
        <a href="#" className="ek-header__logo" aria-label="Earth & Kiln Studio Home">
          Earth & Kiln Studio
        </a>

        <nav className="ek-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ek-header__link">Home</a>
          <a href="#offerings" className="ek-header__link">Studio Offerings</a>
          <a href="#footer" className="ek-header__link">Contact</a>
        </nav>

        <div className="ek-header__actions">
          <a href="mailto:studio@earthandkiln.com" className="ek-header__cta">
            Book Potter's Wheel Class
          </a>
          <button
            type="button"
            className="ek-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ek-header__bar" />
            <span className="ek-header__bar" />
            <span className="ek-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ek-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#offerings" onClick={() => setMenuOpen(false)}>Studio Offerings</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

