import React from 'react';
import './StudioOfferings.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "Beginner Wheel Throwing Workshop",
    "tag": "3hr Intensive",
    "desc": "Hands-on guidance centering clay, opening, and pulling cylinder forms."
  },
  {
    "step": "Phase 02",
    "title": "Handmade Stoneware Tableware",
    "tag": "Ceramic Shop",
    "desc": "Microwave and dishwasher-safe speckled clay dinner plates and mugs."
  },
  {
    "step": "Phase 03",
    "title": "Wood-Fired Anagama Kiln Residencies",
    "tag": "Master Class",
    "desc": "48-hour continuous wood firings creating natural ash glaze patinas."
  },
  {
    "step": "Phase 04",
    "title": "Monthly Open Studio Membership",
    "tag": "24/7 Access",
    "desc": "Dedicated shelf space, studio glazes, and unlimited high-fire kiln firings."
  }
];

export function StudioOfferings() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.ek-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="ek-timeline" id="offerings" aria-labelledby="ek-timeline-title">
      <div className="ek-timeline__inner">
        <div className="ek-timeline__header">
          <p className="ek-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="ek-timeline-title" className="ek-timeline__title">
            Studio Offerings
          </h2>
          <p className="ek-timeline__desc">
            Hand-thrown functional stoneware ceramics, atmospheric wood-fired kilns, and hands-on wheel throwing workshops.
          </p>
        </div>

        <div ref={trackRef} className="ek-timeline__track">
          <div className="ek-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="ek-timeline__node">
              <div className="ek-timeline__marker" aria-hidden="true">
                <span className="ek-timeline__dot" />
              </div>
              <div className="ek-timeline__card">
                <div className="ek-timeline__card-top">
                  <span className="ek-timeline__step">{m.step}</span>
                  <span className="ek-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="ek-timeline__card-title">{m.title}</h3>
                <p className="ek-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

