import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sm-header${scrolled ? ' sm-header--scrolled' : ''}`} role="banner">
      <div className="sm-header__inner">
        <a href="#" className="sm-header__logo" aria-label="SmoothMove Elite Movers Home">
          SmoothMove Elite Movers
        </a>

        <nav className="sm-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sm-header__link">Home</a>
          <a href="#services" className="sm-header__link">Moving Services</a>
          <a href="#footer" className="sm-header__link">Contact</a>
        </nav>

        <div className="sm-header__actions">
          <a href="mailto:quotes@smoothmovemovers.com" className="sm-header__cta">
            Get Instant Moving Estimate
          </a>
          <button
            type="button"
            className="sm-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sm-header__bar" />
            <span className="sm-header__bar" />
            <span className="sm-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sm-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#services" onClick={() => setMenuOpen(false)}>Moving Services</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

