  },
  {
    "title": "Interstate Long-Distance Moving",
    "tag": "Coast-to-Coast",
    "desc": "Guaranteed direct delivery dates without multi-client truck sharing."
  },
  {
    "title": "Climate-Controlled Vault Storage",
    "tag": "Secure Storage",
    "desc": "Private wooden vault containers inside 24/7 guarded, humidity-regulated hubs."
  },
  {
    "title": "Office & Commercial Relocation",
    "tag": "Business Moving",
    "desc": "Weekend technology disconnect, rolling server racks, and desk reassembly."
  }
];

export function MovingServices() {
  const [activeTab, setActiveTab] = useState(0);

  return (
    <section className="sm-tabs" id="services" aria-labelledby="sm-tabs-title">
      <div className="sm-tabs__inner">
        <div className="sm-tabs__header">
          <p className="sm-tabs__eyebrow">Interactive Directory</p>
          <h2 id="sm-tabs-title" className="sm-tabs__title">
            Moving Services
          </h2>
          <p className="sm-tabs__desc">
            White-glove residential relocations, custom fine-art crating, and humidity-controlled private vault storage.
          </p>
        </div>

        <div className="sm-tabs__nav" role="tablist" aria-label="Moving Services Tabs">
          {ITEMS.map((item, idx) => (
            <button
              key={item.title}
              type="button"
              role="tab"
              aria-selected={activeTab === idx}
              className={`sm-tabs__tab${activeTab === idx ? ' sm-tabs__tab--active' : ''}`}
              onClick={() => setActiveTab(idx)}
            >
              {item.title}
            </button>
          ))}
        </div>

        <div className="sm-tabs__showcase" role="tabpanel">
          <div className="sm-tabs__panel-top">
            <span className="sm-tabs__panel-tag">{ITEMS[activeTab]?.tag}</span>
            <span className="sm-tabs__panel-index">Tier 0{activeTab + 1}</span>
          </div>
          <h3 className="sm-tabs__panel-title">{ITEMS[activeTab]?.title}</h3>
          <p className="sm-tabs__panel-desc">{ITEMS[activeTab]?.desc}</p>
          <div className="sm-tabs__panel-footer">
            <a href="mailto:quotes@smoothmovemovers.com" className="sm-tabs__btn">
              Inquire About {ITEMS[activeTab]?.title}
            </a>
          </div>
        </div>

        <div className="sm-tabs__grid">
          {ITEMS.map((item, idx) => (
            <div
              key={item.title}
              className={`sm-tabs__card${activeTab === idx ? ' sm-tabs__card--active' : ''}`}
              onClick={() => setActiveTab(idx)}
            >
              <div className="sm-tabs__card-top">
                <span className="sm-tabs__card-num">0{idx + 1}</span>
                <span className="sm-tabs__card-tag">{item.tag}</span>
              </div>
              <h4 className="sm-tabs__card-title">{item.title}</h4>
              <p className="sm-tabs__card-desc">{item.desc}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

