import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`tw-header${scrolled ? ' tw-header--scrolled' : ''}`} role="banner">
      <div className="tw-header__inner">
        <a href="#" className="tw-header__logo" aria-label="TerraWear Sustainable Activewear Home">
          TerraWear Sustainable Activewear
        </a>

        <nav className="tw-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="tw-header__link">Home</a>
          <a href="#collection" className="tw-header__link">Core Performance Gear</a>
          <a href="#footer" className="tw-header__link">Contact</a>
        </nav>

        <div className="tw-header__actions">
          <a href="mailto:support@terrawearactive.com" className="tw-header__cta">
            Shop Sustainable Drop
          </a>
          <button
            type="button"
            className="tw-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="tw-header__bar" />
            <span className="tw-header__bar" />
            <span className="tw-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="tw-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#collection" onClick={() => setMenuOpen(false)}>Core Performance Gear</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

