import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`mm-header${scrolled ? ' mm-header--scrolled' : ''}`} role="banner">
      <div className="mm-header__inner">
        <a href="#" className="mm-header__logo" aria-label="Metropolitan Digital Art Hall Home">
          Metropolitan Digital Art Hall
        </a>

        <nav className="mm-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="mm-header__link">Home</a>
          <a href="#exhibitions" className="mm-header__link">Current Exhibitions</a>
          <a href="#footer" className="mm-header__link">Contact</a>
        </nav>

        <div className="mm-header__actions">
          <a href="mailto:tickets@metropolitanmodernart.org" className="mm-header__cta">
            Reserve Timed Entry
          </a>
          <button
            type="button"
            className="mm-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="mm-header__bar" />
            <span className="mm-header__bar" />
            <span className="mm-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="mm-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#exhibitions" onClick={() => setMenuOpen(false)}>Current Exhibitions</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

