import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`eg-header${scrolled ? ' eg-header--scrolled' : ''}`} role="banner">
      <div className="eg-header__inner">
        <a href="#" className="eg-header__logo" aria-label="EcoGuard Botanical Defense Home">
          EcoGuard Botanical Defense
        </a>

        <nav className="eg-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="eg-header__link">Home</a>
          <a href="#solutions" className="eg-header__link">Pest Solutions</a>
          <a href="#footer" className="eg-header__link">Contact</a>
        </nav>

        <div className="eg-header__actions">
          <a href="mailto:dispatch@ecoguarddefense.com" className="eg-header__cta">
            Schedule Inspection
          </a>
          <button
            type="button"
            className="eg-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="eg-header__bar" />
            <span className="eg-header__bar" />
            <span className="eg-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="eg-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#solutions" onClick={() => setMenuOpen(false)}>Pest Solutions</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

