import React from 'react';
import './PestSolutions.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Botanical Barrier Home Perimeter",
    "tag": "Child & Pet Safe",
    "desc": "Organic essential oil barrier keeping ants, spiders, and roaches out."
  },
  {
    "title": "Structural Rodent Proofing",
    "tag": "Permanent",
    "desc": "Sealing foundational entry points with heavy gauge steel mesh & copper wire."
  },
  {
    "title": "Eco-Friendly Termite Interception",
    "tag": "Monitoring",
    "desc": "Subterranean baiting stations eliminating colonies without pumping chemical poisons."
  },
  {
    "title": "Mosquito & Tick Yard Misting",
    "tag": "Seasonal",
    "desc": "Garlic and thyme oil micro-fogging drastically cutting biting insect counts."
  }
];

export function PestSolutions() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.eg-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="eg-catalog" id="solutions" aria-labelledby="eg-catalog-title">
      <div className="eg-catalog__inner">
        <div className="eg-catalog__header">
          <p className="eg-catalog__eyebrow">Featured Highlights</p>
          <h2 id="eg-catalog-title" className="eg-catalog__title">
            Pest Solutions
          </h2>
          <p className="eg-catalog__desc">
            Non-toxic botanical perimeter exclusion, organic pest prevention, and structural rodent defense for health-conscious homes.
          </p>
        </div>

        <div ref={gridRef} className="eg-catalog__grid">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="eg-card" style={{ transitionDelay: `${idx * 60}ms` }}>
              <div className="eg-card__top">
                <span className="eg-card__index">0{idx + 1}</span>
                <span className="eg-card__tag">{item.tag}</span>
              </div>
              <h3 className="eg-card__title">{item.title}</h3>
              <p className="eg-card__desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

