import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`bh-header${scrolled ? ' bh-header--scrolled' : ''}`} role="banner">
      <div className="bh-header__inner">
        <a href="#" className="bh-header__logo" aria-label="Blue Horizon Yacht Charters Home">
          Blue Horizon Yacht Charters
        </a>

        <nav className="bh-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="bh-header__link">Home</a>
          <a href="#fleet" className="bh-header__link">Charter Fleet</a>
          <a href="#footer" className="bh-header__link">Contact</a>
        </nav>

        <div className="bh-header__actions">
          <a href="mailto:captain@bluehorizonsailing.com" className="bh-header__cta">
            Book Yacht Charter
          </a>
          <button
            type="button"
            className="bh-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="bh-header__bar" />
            <span className="bh-header__bar" />
            <span className="bh-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="bh-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#fleet" onClick={() => setMenuOpen(false)}>Charter Fleet</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

