import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`qm-header${scrolled ? ' qm-header--scrolled' : ''}`} role="banner">
      <div className="qm-header__inner">
        <a href="#" className="qm-header__logo" aria-label="QuantMasters Academy Home">
          QuantMasters Academy
        </a>

        <nav className="qm-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="qm-header__link">Home</a>
          <a href="#curriculum" className="qm-header__link">Academy Tracks</a>
          <a href="#footer" className="qm-header__link">Contact</a>
        </nav>

        <div className="qm-header__actions">
          <a href="mailto:admissions@quantmastersacademy.com" className="qm-header__cta">
            Take Diagnostic Assessment
          </a>
          <button
            type="button"
            className="qm-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="qm-header__bar" />
            <span className="qm-header__bar" />
            <span className="qm-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="qm-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#curriculum" onClick={() => setMenuOpen(false)}>Academy Tracks</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

