import React from 'react';
import './AcademyTracks.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "Mathematical Olympiad Prep",
    "tag": "AMC 10/12 & AIME",
    "desc": "Number theory, combinatorics, and synthetic Euclidean geometry proofs."
  },
  {
    "step": "Phase 02",
    "title": "AP & Competitive Physics",
    "tag": "Mechanics & E&M",
    "desc": "Calculus-based physics mastery with experimental problem-solving labs."
  },
  {
    "step": "Phase 03",
    "title": "USACO Algorithmic Coding",
    "tag": "Silver to Platinum",
    "desc": "Dynamic programming, graph algorithms, and segment trees in C++ and Python."
  },
  {
    "step": "Phase 04",
    "title": "Ivy League STEM Admissions Mentorship",
    "tag": "Advisory",
    "desc": "Guiding high schoolers in independent peer-reviewed STEM research publications."
  }
];

export function AcademyTracks() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.qm-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="qm-timeline" id="curriculum" aria-labelledby="qm-timeline-title">
      <div className="qm-timeline__inner">
        <div className="qm-timeline__header">
          <p className="qm-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="qm-timeline-title" className="qm-timeline__title">
            Academy Tracks
          </h2>
          <p className="qm-timeline__desc">
            Rigorous Olympiad mathematics, university-level physics labs, and competitive algorithmic problem solving mentorship.
          </p>
        </div>

        <div ref={trackRef} className="qm-timeline__track">
          <div className="qm-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="qm-timeline__node">
              <div className="qm-timeline__marker" aria-hidden="true">
                <span className="qm-timeline__dot" />
              </div>
              <div className="qm-timeline__card">
                <div className="qm-timeline__card-top">
                  <span className="qm-timeline__step">{m.step}</span>
                  <span className="qm-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="qm-timeline__card-title">{m.title}</h3>
                <p className="qm-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

