import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`er-header${scrolled ? ' er-header--scrolled' : ''}`} role="banner">
      <div className="er-header__inner">
        <a href="#" className="er-header__logo" aria-label="Elevation Roastery Home">
          Elevation Roastery
        </a>

        <nav className="er-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="er-header__link">Home</a>
          <a href="#coffees" className="er-header__link">Single-Origin Lots</a>
          <a href="#footer" className="er-header__link">Contact</a>
        </nav>

        <div className="er-header__actions">
          <a href="mailto:beans@elevationroastery.com" className="er-header__cta">
            Shop Whole Bean
          </a>
          <button
            type="button"
            className="er-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="er-header__bar" />
            <span className="er-header__bar" />
            <span className="er-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="er-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#coffees" onClick={() => setMenuOpen(false)}>Single-Origin Lots</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
