import React from 'react';
import './Single-OriginLots.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Ethiopia Yirgacheffe Natural",
    "tag": "$22 / 12oz",
    "desc": "Heirloom varietal with jasmine floral aroma, bergamot, and sweet blueberry."
  },
  {
    "title": "Colombia Huila Pink Bourbon",
    "tag": "$24 / 12oz",
    "desc": "Anaerobic honey process yielding crisp guava, passionfruit, and panela sugar."
  },
  {
    "title": "Guatemala Antigua Washed",
    "tag": "$20 / 12oz",
    "desc": "Volcanic soil cultivation with dark chocolate, candied almond, and orange peel."
  },
  {
    "title": "Nitro Cold Brew Keg Service",
    "tag": "Commercial",
    "desc": "Creamy draft nitro cold brew delivered weekly to modern tech offices."
  }
];

export function Single-OriginLots() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.er-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="er-catalog" id="coffees" aria-labelledby="er-catalog-title">
      <div className="er-catalog__inner">
        <div className="er-catalog__header">
          <p className="er-catalog__eyebrow">Featured Highlights</p>
          <h2 id="er-catalog-title" className="er-catalog__title">
            Single-Origin Lots
          </h2>
          <p className="er-catalog__desc">
            High-altitude single-origin microlots roasted to order with precision thermodynamic profiling and cupping scores.
          </p>
        </div>

        <div ref={gridRef} className="er-catalog__grid">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="er-card" style={{ transitionDelay: `${idx * 60}ms` }}>
              <div className="er-card__top">
                <span className="er-card__index">0{idx + 1}</span>
                <span className="er-card__tag">{item.tag}</span>
              </div>
              <h3 className="er-card__title">{item.title}</h3>
              <p className="er-card__desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

