        <nav className="sl-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sl-header__link">Home</a>
          <a href="#films" className="sl-header__link">Now Showing</a>
          <a href="#footer" className="sl-header__link">Contact</a>
        </nav>

        <div className="sl-header__actions">
          <a href="mailto:boxoffice@starlightpicturehouse.com" className="sl-header__cta">
            Reserve Cinema Seats
          </a>
          <button
            type="button"
            className="sl-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sl-header__bar" />
            <span className="sl-header__bar" />
            <span className="sl-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
