import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`cb-header${scrolled ? ' cb-header--scrolled' : ''}`} role="banner">
      <div className="cb-header__inner">
        <a href="#" className="cb-header__logo" aria-label="Crumbles Dedicated Bakery Home">
          Crumbles Dedicated Bakery
        </a>

        <nav className="cb-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="cb-header__link">Home</a>
          <a href="#menu" className="cb-header__link">Daily Gluten-Free Menu</a>
          <a href="#footer" className="cb-header__link">Contact</a>
        </nav>

        <div className="cb-header__actions">
          <a href="mailto:bakery@crumblesdedicatedbakery.com" className="cb-header__cta">
            Order Custom Cake
          </a>
          <button
            type="button"
            className="cb-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="cb-header__bar" />
            <span className="cb-header__bar" />
            <span className="cb-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="cb-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#menu" onClick={() => setMenuOpen(false)}>Daily Gluten-Free Menu</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

