import React, { useState } from 'react';
import './DailyGluten-FreeMenu.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Artisan Artisan Sourdough Loaf",
    "tag": "$11.00",
    "desc": "Certified celiac safe sourdough with crunchy blistered crust and soft crumb."
  },
  {
    "title": "Salted Caramel Celebration Cake",
    "tag": "$55.00",
    "desc": "Fluffy vanilla sponge layered with house-made salted caramel and buttercream."
  },
  {
    "title": "Cinnamon Pecan Sticky Rolls",
    "tag": "$5.50",
    "desc": "Warm brioche-style rolls baked with maple glaze and toasted Georgia pecans."
  },
  {
    "title": "Savory Cheddar Chive Scones",
    "tag": "$4.75",
    "desc": "Flaky aged sharp cheddar scones brushed with melted garlic herb butter."
  }
];

export function DailyGluten-FreeMenu() {
  const [activeTab, setActiveTab] = useState(0);

  return (
    <section className="cb-tabs" id="menu" aria-labelledby="cb-tabs-title">
      <div className="cb-tabs__inner">
        <div className="cb-tabs__header">
          <p className="cb-tabs__eyebrow">Interactive Directory</p>
          <h2 id="cb-tabs-title" className="cb-tabs__title">
            Daily Gluten-Free Menu
          </h2>
          <p className="cb-tabs__desc">
            Certified gluten-free artisan sourdough, tiered celebration cakes, and morning pastries prepared in a dedicated facility.
          </p>
        </div>

        <div className="cb-tabs__nav" role="tablist" aria-label="Daily Gluten-Free Menu Tabs">
          {ITEMS.map((item, idx) => (
            <button
              key={item.title}
              type="button"
              role="tab"
              aria-selected={activeTab === idx}
              className={`cb-tabs__tab${activeTab === idx ? ' cb-tabs__tab--active' : ''}`}
              onClick={() => setActiveTab(idx)}
            >
              {item.title}
            </button>
          ))}
        </div>

        <div className="cb-tabs__showcase" role="tabpanel">
          <div className="cb-tabs__panel-top">
            <span className="cb-tabs__panel-tag">{ITEMS[activeTab]?.tag}</span>
            <span className="cb-tabs__panel-index">Tier 0{activeTab + 1}</span>
          </div>
          <h3 className="cb-tabs__panel-title">{ITEMS[activeTab]?.title}</h3>
          <p className="cb-tabs__panel-desc">{ITEMS[activeTab]?.desc}</p>
          <div className="cb-tabs__panel-footer">
            <a href="mailto:bakery@crumblesdedicatedbakery.com" className="cb-tabs__btn">
              Inquire About {ITEMS[activeTab]?.title}
            </a>
          </div>
        </div>

        <div className="cb-tabs__grid">
          {ITEMS.map((item, idx) => (
            <div
              key={item.title}
              className={`cb-tabs__card${activeTab === idx ? ' cb-tabs__card--active' : ''}`}
              onClick={() => setActiveTab(idx)}
            >
              <div className="cb-tabs__card-top">
                <span className="cb-tabs__card-num">0{idx + 1}</span>
                <span className="cb-tabs__card-tag">{item.tag}</span>
              </div>
              <h4 className="cb-tabs__card-title">{item.title}</h4>
              <p className="cb-tabs__card-desc">{item.desc}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

