import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`fo-header${scrolled ? ' fo-header--scrolled' : ''}`} role="banner">
      <div className="fo-header__inner">
        <a href="#" className="fo-header__logo" aria-label="The Foundry Urban Loft Home">
          The Foundry Urban Loft
        </a>

        <nav className="fo-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="fo-header__link">Home</a>
          <a href="#spaces" className="fo-header__link">Event Spaces</a>
          <a href="#footer" className="fo-header__link">Contact</a>
        </nav>

        <div className="fo-header__actions">
          <a href="mailto:events@thefoundryurbanloft.com" className="fo-header__cta">
            Schedule Venue Tour
          </a>
          <button
            type="button"
            className="fo-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="fo-header__bar" />
            <span className="fo-header__bar" />
            <span className="fo-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="fo-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#spaces" onClick={() => setMenuOpen(false)}>Event Spaces</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

