import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`pb-header${scrolled ? ' pb-header--scrolled' : ''}`} role="banner">
      <div className="pb-header__inner">
        <a href="#" className="pb-header__logo" aria-label="Pulse Biometrics Systems Home">
          Pulse Biometrics Systems
        </a>

        <nav className="pb-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="pb-header__link">Home</a>
          <a href="#hardware" className="pb-header__link">Diagnostic Hardware</a>
          <a href="#footer" className="pb-header__link">Contact</a>
        </nav>

        <div className="pb-header__actions">
          <a href="mailto:clinical@pulsebiometrics.com" className="pb-header__cta">
            Request Clinical Trial
          </a>
          <button
            type="button"
            className="pb-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="pb-header__bar" />
            <span className="pb-header__bar" />
            <span className="pb-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="pb-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#hardware" onClick={() => setMenuOpen(false)}>Diagnostic Hardware</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

