import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`vs-header${scrolled ? ' vs-header--scrolled' : ''}`} role="banner">
      <div className="vs-header__inner">
        <a href="#" className="vs-header__logo" aria-label="VectorScale DB Home">
          VectorScale DB
        </a>

        <nav className="vs-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="vs-header__link">Home</a>
          <a href="#capabilities" className="vs-header__link">Engine Capabilities</a>
          <a href="#footer" className="vs-header__link">Contact</a>
        </nav>

        <div className="vs-header__actions">
          <a href="mailto:infra@vectorscaledb.com" className="vs-header__cta">
            Deploy Cluster
          </a>
          <button
            type="button"
            className="vs-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="vs-header__bar" />
            <span className="vs-header__bar" />
            <span className="vs-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="vs-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#capabilities" onClick={() => setMenuOpen(false)}>Engine Capabilities</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

