import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`kt-header${scrolled ? ' kt-header--scrolled' : ''}`} role="banner">
      <div className="kt-header__inner">
        <a href="#" className="kt-header__logo" aria-label="K-Trace Observability Home">
          K-Trace Observability
        </a>

        <nav className="kt-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="kt-header__link">Home</a>
          <a href="#engines" className="kt-header__link">Telemetry Engines</a>
          <a href="#footer" className="kt-header__link">Contact</a>
        </nav>

        <div className="kt-header__actions">
          <a href="mailto:ops@ktrace.io" className="kt-header__cta">
            Install DaemonSet
          </a>
          <button
            type="button"
            className="kt-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="kt-header__bar" />
            <span className="kt-header__bar" />
            <span className="kt-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="kt-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#engines" onClick={() => setMenuOpen(false)}>Telemetry Engines</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

