import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ng-header${scrolled ? ' ng-header--scrolled' : ''}`} role="banner">
      <div className="ng-header__inner">
        <a href="#" className="ng-header__logo" aria-label="Nexus Gateway Home">
          Nexus Gateway
        </a>

        <nav className="ng-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ng-header__link">Home</a>
          <a href="#features" className="ng-header__link">Gateway Features</a>
          <a href="#footer" className="ng-header__link">Contact</a>
        </nav>

        <div className="ng-header__actions">
          <a href="mailto:team@nexusgateway.ai" className="ng-header__cta">
            Connect API Key
          </a>
          <button
            type="button"
            className="ng-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ng-header__bar" />
            <span className="ng-header__bar" />
            <span className="ng-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ng-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#features" onClick={() => setMenuOpen(false)}>Gateway Features</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

