import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`cl-header${scrolled ? ' cl-header--scrolled' : ''}`} role="banner">
      <div className="cl-header__inner">
        <a href="#" className="cl-header__logo" aria-label="CloudLedger FinOps Home">
          CloudLedger FinOps
        </a>

        <nav className="cl-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="cl-header__link">Home</a>
          <a href="#tools" className="cl-header__link">Optimization Tools</a>
          <a href="#footer" className="cl-header__link">Contact</a>
        </nav>

        <div className="cl-header__actions">
          <a href="mailto:savings@cloudledger.io" className="cl-header__cta">
            Audit Cloud Spend
          </a>
          <button
            type="button"
            className="cl-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
