import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sv-header${scrolled ? ' sv-header--scrolled' : ''}`} role="banner">
      <div className="sv-header__inner">
        <a href="#" className="sv-header__logo" aria-label="SpecVigil API Testing Home">
          SpecVigil API Testing
        </a>

        <nav className="sv-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sv-header__link">Home</a>
          <a href="#suites" className="sv-header__link">Test Suites</a>
          <a href="#footer" className="sv-header__link">Contact</a>
        </nav>

        <div className="sv-header__actions">
          <a href="mailto:support@specvigil.dev" className="sv-header__cta">
            Test Your API
          </a>
          <button
            type="button"
            className="sv-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sv-header__bar" />
            <span className="sv-header__bar" />
            <span className="sv-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sv-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#suites" onClick={() => setMenuOpen(false)}>Test Suites</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

