import React from 'react';
import './TestSuites.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Automated Contract Regression",
    "tag": "CI/CD Native",
    "desc": "Diff pull requests against live OpenAPI 3.1 schemas to flag backward-incompatible breaking field removals."
  },
  {
    "title": "Stateful Mock Servers",
    "tag": "Faker Engine",
    "desc": "Spin up ultra-fast ephemeral mock servers with realistic relational data and latency simulation for frontend teams."
  },
  {
    "title": "Fuzzing & Boundary Testing",
    "tag": "Security Fuzz",
    "desc": "Generate thousands of malicious payloads to uncover unhandled null pointers and SQL/NoSQL injections."
  },
  {
    "title": "SDK Generation Pipeline",
    "tag": "TypeScript/Go/Py",
    "desc": "Compile bulletproof, strongly-typed client libraries directly from your validated contract specifications."
  }
];

export function TestSuites() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.sv-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="sv-catalog" id="suites" aria-labelledby="sv-catalog-title">
      <div className="sv-catalog__inner">
        <div className="sv-catalog__header">
          <p className="sv-catalog__eyebrow">Featured Highlights</p>
          <h2 id="sv-catalog-title" className="sv-catalog__title">
            Test Suites
          </h2>
          <p className="sv-catalog__desc">
            Automated OpenAPI and GraphQL schema validation, contract drift detection, and synthetic mock environment testing.
          </p>
        </div>

        <div ref={gridRef} className="sv-catalog__grid">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="sv-card" style={{ transitionDelay: `${idx * 60}ms` }}>
              <div className="sv-card__top">
                <span className="sv-card__index">0{idx + 1}</span>
                <span className="sv-card__tag">{item.tag}</span>
              </div>
              <h3 className="sv-card__title">{item.title}</h3>
              <p className="sv-card__desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

