import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ab-header${scrolled ? ' ab-header--scrolled' : ''}`} role="banner">
      <div className="ab-header__inner">
        <a href="#" className="ab-header__logo" aria-label="Apex BareMetal Cloud Home">
          Apex BareMetal Cloud
        </a>

        <nav className="ab-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ab-header__link">Home</a>
          <a href="#hardware" className="ab-header__link">Hardware Configurations</a>
          <a href="#footer" className="ab-header__link">Contact</a>
        </nav>

        <div className="ab-header__actions">
          <a href="mailto:sales@apexmetal.cloud" className="ab-header__cta">
            Provision Cluster
          </a>
          <button
            type="button"
            className="ab-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ab-header__bar" />
            <span className="ab-header__bar" />
            <span className="ab-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ab-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#hardware" onClick={() => setMenuOpen(false)}>Hardware Configurations</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

