import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ts-header${scrolled ? ' ts-header--scrolled' : ''}`} role="banner">
      <div className="ts-header__inner">
        <a href="#" className="ts-header__logo" aria-label="TitanSQL Distributed Home">
          TitanSQL Distributed
        </a>

        <nav className="ts-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ts-header__link">Home</a>
          <a href="#architecture" className="ts-header__link">Architecture Highlights</a>
          <a href="#footer" className="ts-header__link">Contact</a>
        </nav>

        <div className="ts-header__actions">
          <a href="mailto:team@titansql.com" className="ts-header__cta">
            Create Free Cluster
          </a>
          <button
            type="button"
            className="ts-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ts-header__bar" />
            <span className="ts-header__bar" />
            <span className="ts-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ts-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#architecture" onClick={() => setMenuOpen(false)}>Architecture Highlights</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

