import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`hq-header${scrolled ? ' hq-header--scrolled' : ''}`} role="banner">
      <div className="hq-header__inner">
        <a href="#" className="hq-header__logo" aria-label="Helios Quantum Lab Home">
          Helios Quantum Lab
        </a>

        <nav className="hq-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="hq-header__link">Home</a>
          <a href="#modules" className="hq-header__link">Research Modules</a>
          <a href="#footer" className="hq-header__link">Contact</a>
        </nav>

        <div className="hq-header__actions">
          <a href="mailto:research@heliosquantum.org" className="hq-header__cta">
            Simulate Circuit
          </a>
          <button
            type="button"
            className="hq-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="hq-header__bar" />
            <span className="hq-header__bar" />
            <span className="hq-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="hq-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#modules" onClick={() => setMenuOpen(false)}>Research Modules</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

