import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sn-header${scrolled ? ' sn-header--scrolled' : ''}`} role="banner">
      <div className="sn-header__inner">
        <a href="#" className="sn-header__logo" aria-label="Synapse TeleNeurology Home">
          Synapse TeleNeurology
        </a>

        <nav className="sn-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sn-header__link">Home</a>
          <a href="#clinics" className="sn-header__link">Specialized Clinics</a>
          <a href="#footer" className="sn-header__link">Contact</a>
        </nav>

        <div className="sn-header__actions">
          <a href="mailto:intake@synapseneuro.com" className="sn-header__cta">
            Schedule Evaluation
          </a>
          <button
            type="button"
            className="sn-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sn-header__bar" />
            <span className="sn-header__bar" />
            <span className="sn-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sn-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#clinics" onClick={() => setMenuOpen(false)}>Specialized Clinics</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

