import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`kl-header${scrolled ? ' kl-header--scrolled' : ''}`} role="banner">
      <div className="kl-header__inner">
        <a href="#" className="kl-header__logo" aria-label="Kinetic Lab Sports Medicine Home">
          Kinetic Lab Sports Medicine
        </a>

        <nav className="kl-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="kl-header__link">Home</a>
          <a href="#protocols" className="kl-header__link">Rehab Protocols</a>
          <a href="#footer" className="kl-header__link">Contact</a>
        </nav>

        <div className="kl-header__actions">
          <a href="mailto:clinic@kineticlab.com" className="kl-header__cta">
            Book Assessment
          </a>
          <button
            type="button"
            className="kl-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="kl-header__bar" />
            <span className="kl-header__bar" />
            <span className="kl-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="kl-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#protocols" onClick={() => setMenuOpen(false)}>Rehab Protocols</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

