import React from 'react';
import './RehabProtocols.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "ACL Reconstruction Return-to-Play",
    "tag": "Force Plate Symmetry",
    "desc": "Isokinetic dynamometry and triple hop symmetry testing to eliminate secondary graft re-tear risks."
  },
  {
    "step": "Phase 02",
    "title": "High-Speed Running Gait Analysis",
    "tag": "Qualisys 3D Mocap",
    "desc": "12-camera motion analysis quantifying pelvic drop, braking forces, and ground contact asymmetries."
  },
  {
    "step": "Phase 03",
    "title": "Overhead Throwing Arm Protocol",
    "tag": "Electromyography",
    "desc": "Valgus torque assessment and scapular dyskinesis correction for baseball pitchers and tennis players."
  },
  {
    "step": "Phase 04",
    "title": "Blood Flow Restriction Training",
    "tag": "Delfi Personalized BFR",
    "desc": "Hypertrophy and strength gains at low joint loads to accelerate post-operative tendon healing."
  }
];

export function RehabProtocols() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.kl-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="kl-timeline" id="protocols" aria-labelledby="kl-timeline-title">
      <div className="kl-timeline__inner">
        <div className="kl-timeline__header">
          <p className="kl-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="kl-timeline-title" className="kl-timeline__title">
            Rehab Protocols
          </h2>
          <p className="kl-timeline__desc">
            High-speed 3D motion capture, force-plate kinetic assessments, and customized neuromuscular return-to-sport protocols.
          </p>
        </div>

        <div ref={trackRef} className="kl-timeline__track">
          <div className="kl-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="kl-timeline__node">
              <div className="kl-timeline__marker" aria-hidden="true">
                <span className="kl-timeline__dot" />
              </div>
              <div className="kl-timeline__card">
                <div className="kl-timeline__card-top">
                  <span className="kl-timeline__step">{m.step}</span>
                  <span className="kl-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="kl-timeline__card-title">{m.title}</h3>
                <p className="kl-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

