import React from 'react';
import './ClinicalTreatments.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Fractional CO2 Laser Resurfacing",
    "tag": "Deep Remodeling",
    "desc": "Ablative micro-thermal zones stimulating neo-collagenesis for deep acne scarring and photodamage."
  },
  {
    "title": "Mohs Micrographic Surgery",
    "tag": "99% Clear Margins",
    "desc": "Same-day microscopic margin mapping for basal and squamous cell carcinomas with aesthetic reconstruction."
  },
  {
    "title": "Vascular Laser Therapy",
    "tag": "Candela Vbeam",
    "desc": "Pulsed dye laser specifically targeting facial telangiectasias, rosacea redness, and port-wine stains."
  },
  {
    "title": "Biologic Immunotherapy for Psoriasis",
    "tag": "IL-17/IL-23 Inhibitors",
    "desc": "Targeted biologic regimens achieving 90\u2013100% skin clearance for chronic severe plaque psoriasis."
  }
];

export function ClinicalTreatments() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.ad-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="ad-catalog" id="treatments" aria-labelledby="ad-catalog-title">
      <div className="ad-catalog__inner">
        <div className="ad-catalog__header">
          <p className="ad-catalog__eyebrow">Featured Highlights</p>
          <h2 id="ad-catalog-title" className="ad-catalog__title">
            Clinical Treatments
          </h2>
          <p className="ad-catalog__desc">
            Advanced laser skin resurfacing, digital dermoscopy mole mapping, and personalized dermatological medical therapies.
          </p>
        </div>

        <div ref={gridRef} className="ad-catalog__grid">
          {ITEMS.map((item, idx) => (
            <article key={item.title} className="ad-card" style={{ transitionDelay: `${idx * 60}ms` }}>
              <div className="ad-card__top">
                <span className="ad-card__index">0{idx + 1}</span>
                <span className="ad-card__tag">{item.tag}</span>
              </div>
              <h3 className="ad-card__title">{item.title}</h3>
              <p className="ad-card__desc">{item.desc}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

