import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ls-header${scrolled ? ' ls-header--scrolled' : ''}`} role="banner">
      <div className="ls-header__inner">
        <a href="#" className="ls-header__logo" aria-label="Little Steps Pediatric Therapy Home">
          Little Steps Pediatric Therapy
        </a>

        <nav className="ls-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ls-header__link">Home</a>
          <a href="#programs" className="ls-header__link">Therapy Programs</a>
          <a href="#footer" className="ls-header__link">Contact</a>
        </nav>

        <div className="ls-header__actions">
          <a href="mailto:admissions@littlestepstherapy.org" className="ls-header__cta">
            Request Evaluation
          </a>
          <button
            type="button"
            className="ls-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ls-header__bar" />
            <span className="ls-header__bar" />
            <span className="ls-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ls-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#programs" onClick={() => setMenuOpen(false)}>Therapy Programs</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

