import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ar-header${scrolled ? ' ar-header--scrolled' : ''}`} role="banner">
      <div className="ar-header__inner">
        <a href="#" className="ar-header__logo" aria-label="Apex Heart Rhythm Institute Home">
          Apex Heart Rhythm Institute
        </a>

        <nav className="ar-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ar-header__link">Home</a>
          <a href="#procedures" className="ar-header__link">Clinical Procedures</a>
          <a href="#footer" className="ar-header__link">Contact</a>
        </nav>

        <div className="ar-header__actions">
          <a href="mailto:clinical@apexheartrhythm.org" className="ar-header__cta">
            Refer a Patient
          </a>
          <button
            type="button"
            className="ar-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ar-header__bar" />
            <span className="ar-header__bar" />
            <span className="ar-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ar-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#procedures" onClick={() => setMenuOpen(false)}>Clinical Procedures</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

