import React from 'react';
import './ClinicalPathways.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "Time-Lapse Embryo Monitoring",
    "tag": "EmbryoScope+",
    "desc": "Continuous artificial intelligence assessment of blastocyst cellular division kinetics without incubator disruption."
  },
  {
    "step": "Phase 02",
    "title": "PGT-A Chromosomal Screening",
    "tag": "Next-Gen Sequencing",
    "desc": "Comprehensive 24-chromosome aneuploidy detection to maximize single embryo transfer implantation success."
  },
  {
    "step": "Phase 03",
    "title": "Social Egg Vitrification",
    "tag": "Flash Cryopreservation",
    "desc": "Ultra-fast vitrification preventing ice crystal formation with >95% post-thaw oocyte survival rates."
  },
  {
    "step": "Phase 04",
    "title": "Recurrent Implantation Failure Panel",
    "tag": "Immunology & Endometrium",
    "desc": "ERA endometrial receptivity array, microbiome testing, and natural killer (NK) cell balance analysis."
  }
];

export function ClinicalPathways() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.no-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="no-timeline" id="pathways" aria-labelledby="no-timeline-title">
      <div className="no-timeline__inner">
        <div className="no-timeline__header">
          <p className="no-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="no-timeline-title" className="no-timeline__title">
            Clinical Pathways
          </h2>
          <p className="no-timeline__desc">
            Next-generation IVF embryology, pre-implantation genetic screening, and fertility preservation reproductive care.
          </p>
        </div>

        <div ref={trackRef} className="no-timeline__track">
          <div className="no-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="no-timeline__node">
              <div className="no-timeline__marker" aria-hidden="true">
                <span className="no-timeline__dot" />
              </div>
              <div className="no-timeline__card">
                <div className="no-timeline__card-top">
                  <span className="no-timeline__step">{m.step}</span>
                  <span className="no-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="no-timeline__card-title">{m.title}</h3>
                <p className="no-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

