import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`ak-header${scrolled ? ' ak-header--scrolled' : ''}`} role="banner">
      <div className="ak-header__inner">
        <a href="#" className="ak-header__logo" aria-label="Aether Keyboards Home">
          Aether Keyboards
        </a>

        <nav className="ak-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="ak-header__link">Home</a>
          <a href="#editions" className="ak-header__link">Flagship Editions</a>
          <a href="#footer" className="ak-header__link">Contact</a>
        </nav>

        <div className="ak-header__actions">
          <a href="mailto:concierge@aetherkeyboards.com" className="ak-header__cta">
            Join Next Group Buy
          </a>
          <button
            type="button"
            className="ak-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="ak-header__bar" />
            <span className="ak-header__bar" />
            <span className="ak-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="ak-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#editions" onClick={() => setMenuOpen(false)}>Flagship Editions</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

