        <div className="se-header__actions">
          <a href="mailto:clay@stoneandember.com" className="se-header__cta">
            Commission Dinnerware
          </a>
          <button
            type="button"
            className="se-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="se-header__bar" />
            <span className="se-header__bar" />
            <span className="se-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
