import React from 'react';
import './KilnCollections.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "Anagama Ash Tasting Plates",
    "tag": "Wood Fired 1300\u00b0C",
    "desc": "Natural wood ash vitrification creating rough crustaceous textures and subtle amber flash marks."
  },
  {
    "step": "Phase 02",
    "title": "Shino Glazed Tea Bowls (Chawan)",
    "tag": "Carbon Trapped",
    "desc": "High-alumina field clay coated in feldspathic glaze with rich iron-bloom speckling and warm tactile rim."
  },
  {
    "step": "Phase 03",
    "title": "Monolithic Architectural Vessels",
    "tag": "Hand Coiled",
    "desc": "Large-scale raw textured sculptural jars balancing organic asymmetry with quiet minimalist presence."
  },
  {
    "step": "Phase 04",
    "title": "Pour-Over Dripper & Server Suite",
    "tag": "Custom Wheel Turned",
    "desc": "Precision fluted ceramic dripper with thermal mass retention and matching unglazed stoneware decanter."
  }
];

export function KilnCollections() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.se-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="se-timeline" id="collections" aria-labelledby="se-timeline-title">
      <div className="se-timeline__inner">
        <div className="se-timeline__header">
          <p className="se-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="se-timeline-title" className="se-timeline__title">
            Kiln Collections
