        </a>

        <nav className="do-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="do-header__link">Home</a>
          <a href="#reserves" className="do-header__link">Harvest Reserves</a>
          <a href="#footer" className="do-header__link">Contact</a>
        </nav>

        <div className="do-header__actions">
          <a href="mailto:orders@domaineolivier.gr" className="do-header__cta">
            Reserve Harvest Allocation
          </a>
          <button
            type="button"
            className="do-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="do-header__bar" />
            <span className="do-header__bar" />
            <span className="do-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="do-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#reserves" onClick={() => setMenuOpen(false)}>Harvest Reserves</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

