import React from 'react';
import './HarvestReserves.css';

interface Item {
  title: string;
  tag: string;
  desc: string;
}

const ITEMS: Item[] = [
  {
    "title": "Early Harvest Reserve (Agourelaio)",
    "tag": "740 mg/kg Polyphenols",
    "desc": "Intense green aromas of artichoke leaf, green almond, and a robust peppery antioxidant finish."
  },
  {
    "title": "Monovarietal Koroneiki Classic",
    "tag": "Estate Bottled",
    "desc": "Harmonious and versatile extra virgin oil with notes of fresh-cut grass, green tomato, and golden apple."
  },
  {
    "title": "Smoked Oak Wood-Infused Oil",
    "tag": "Slow Cold Infused",
    "desc": "Estate olive oil gently cold-steeped over natural wild French oak shavings for grilled meats and roasted vegetables."
  },
  {
    "title": "Truffle Infused Special Reserve",
    "tag": "White Alba Truffles",
    "desc": "Ultra-premium oil steeped with shaved Italian Tuber magnatum pico truffles for finishing risottos and fresh pastas."
  }
];

export function HarvestReserves() {
  const gridRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
          }
        });
      },
      { threshold: 0.15 }
    );

    const cards = gridRef.current?.querySelectorAll('.do-card');
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="do-catalog" id="reserves" aria-labelledby="do-catalog-title">
      <div className="do-catalog__inner">
