import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`kv-header${scrolled ? ' kv-header--scrolled' : ''}`} role="banner">
      <div className="kv-header__inner">
        <a href="#" className="kv-header__logo" aria-label="Kingsman & Vance Bespoke Home">
          Kingsman & Vance Bespoke
        </a>

        <nav className="kv-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="kv-header__link">Home</a>
          <a href="#services" className="kv-header__link">Bespoke Services</a>
          <a href="#footer" className="kv-header__link">Contact</a>
        </nav>

        <div className="kv-header__actions">
          <a href="mailto:tailors@kingsmanvance.co.uk" className="kv-header__cta">
            Book Fitting Consultation
          </a>
          <button
            type="button"
            className="kv-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="kv-header__bar" />
            <span className="kv-header__bar" />
            <span className="kv-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="kv-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#services" onClick={() => setMenuOpen(false)}>Bespoke Services</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

