import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`sa-header${scrolled ? ' sa-header--scrolled' : ''}`} role="banner">
      <div className="sa-header__inner">
        <a href="#" className="sa-header__logo" aria-label="Sonus Valve Audio Home">
          Sonus Valve Audio
        </a>

        <nav className="sa-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="sa-header__link">Home</a>
          <a href="#amplifiers" className="sa-header__link">Amplifier Series</a>
          <a href="#footer" className="sa-header__link">Contact</a>
        </nav>

        <div className="sa-header__actions">
          <a href="mailto:listening@sonusvalve.com" className="sa-header__cta">
            Request Audition
          </a>
          <button
            type="button"
            className="sa-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="sa-header__bar" />
            <span className="sa-header__bar" />
            <span className="sa-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="sa-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#amplifiers" onClick={() => setMenuOpen(false)}>Amplifier Series</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

