import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`kc-header${scrolled ? ' kc-header--scrolled' : ''}`} role="banner">
      <div className="kc-header__inner">
        <a href="#" className="kc-header__logo" aria-label="Kurogane Cutlery Forge Home">
          Kurogane Cutlery Forge
        </a>

        <nav className="kc-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="kc-header__link">Home</a>
          <a href="#blades" className="kc-header__link">Master Blades</a>
          <a href="#footer" className="kc-header__link">Contact</a>
        </nav>

        <div className="kc-header__actions">
          <a href="mailto:orders@kuroganeforge.jp" className="kc-header__cta">
            Browse Knives
          </a>
          <button
            type="button"
            className="kc-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="kc-header__bar" />
            <span className="kc-header__bar" />
            <span className="kc-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="kc-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#blades" onClick={() => setMenuOpen(false)}>Master Blades</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

