import React from 'react';
import './MasterBlades.css';

interface Milestone {
  step: string;
  title: string;
  tag: string;
  desc: string;
}

const MILESTONES: Milestone[] = [
  {
    "step": "Phase 01",
    "title": "Gyuto 240mm Chef Knife",
    "tag": "Shirogami #1 Core",
    "desc": "The quintessential all-rounder blade with convex distal taper, laser-thin edge geometry, and stabilized ebony handle."
  },
  {
    "step": "Phase 02",
    "title": "Kiritsuke 210mm Multi-Purpose",
    "tag": "Tsuchime Hammered",
    "desc": "Traditional angled k-tip blade with dual bevel for precision vegetable push-cuts and protein slicing."
  },
  {
    "step": "Phase 03",
    "title": "Santoku 180mm Three Virtues",
    "tag": "67-Layer Damascus",
    "desc": "Lightweight and perfectly balanced for meat, fish, and herbs with octagonal charred chestnut wa-handle."
  },
  {
    "step": "Phase 04",
    "title": "Custom Water Stone Sharpening Service",
    "tag": "Mirror Polish 8000 Grit",
    "desc": "Hand-sharpened on Japanese natural whetstones, thinning bevels and resetting hair-whittling sharpness."
  }
];

export function MasterBlades() {
  const trackRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-revealed');
          }
        });
      },
      { threshold: 0.2 }
    );

    const nodes = trackRef.current?.querySelectorAll('.kc-timeline__node');
    nodes?.forEach((node) => observer.observe(node));

    return () => observer.disconnect();
  }, []);

  return (
    <section className="kc-timeline" id="blades" aria-labelledby="kc-timeline-title">
      <div className="kc-timeline__inner">
        <div className="kc-timeline__header">
          <p className="kc-timeline__eyebrow">Sequential Roadmap</p>
          <h2 id="kc-timeline-title" className="kc-timeline__title">
            Master Blades
          </h2>
          <p className="kc-timeline__desc">
            Hand-forged multi-layer Damascus kitchen knives, custom stabilized burls, and razor-sharp traditional Japanese bevels.
          </p>
        </div>

        <div ref={trackRef} className="kc-timeline__track">
          <div className="kc-timeline__spine" aria-hidden="true" />
          {MILESTONES.map((m) => (
            <article key={m.title} className="kc-timeline__node">
              <div className="kc-timeline__marker" aria-hidden="true">
                <span className="kc-timeline__dot" />
              </div>
              <div className="kc-timeline__card">
                <div className="kc-timeline__card-top">
                  <span className="kc-timeline__step">{m.step}</span>
                  <span className="kc-timeline__tag">{m.tag}</span>
                </div>
                <h3 className="kc-timeline__card-title">{m.title}</h3>
                <p className="kc-timeline__card-desc">{m.desc}</p>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

