import React, { useState, useEffect } from 'react';
import './Header.css';

export function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 15);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header className={`cm-header${scrolled ? ' cm-header--scrolled' : ''}`} role="banner">
      <div className="cm-header__inner">
        <a href="#" className="cm-header__logo" aria-label="Cloud Mist Tea Reserve Home">
          Cloud Mist Tea Reserve
        </a>

        <nav className="cm-header__nav" aria-label="Main Navigation">
          <a href="#hero" className="cm-header__link">Home</a>
          <a href="#reserves" className="cm-header__link">Reserve Cakes & Loose Leaf</a>
          <a href="#footer" className="cm-header__link">Contact</a>
        </nav>

        <div className="cm-header__actions">
          <a href="mailto:curator@cloudmisttea.com" className="cm-header__cta">
            Explore Tea Vault
          </a>
          <button
            type="button"
            className="cm-header__toggle"
            aria-label="Toggle navigation menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuOpen(!menuOpen)}
          >
            <span className="cm-header__bar" />
            <span className="cm-header__bar" />
            <span className="cm-header__bar" />
          </button>
        </div>
      </div>

      {menuOpen && (
        <div className="cm-header__mobile-menu">
          <a href="#hero" onClick={() => setMenuOpen(false)}>Home</a>
          <a href="#reserves" onClick={() => setMenuOpen(false)}>Reserve Cakes & Loose Leaf</a>
          <a href="#footer" onClick={() => setMenuOpen(false)}>Contact</a>
        </div>
      )}
    </header>
  );
}

